IG$.cVis = {
};

IG$.cVis.base = function(opt) {
	var me = this;
	if (opt && typeof opt == "object") {
		$s.apply(me, opt);
	}
	return me;
};

IG$.cVis.base.prototype = {
	constructor: function() {
	},
	
	mvalue: function(cell, useformatvalue) {
		var r,
			t,
			n;
		if (useformatvalue)
		{
			t = cell.text;
	
			if (t && t.indexOf(",") > -1)
			{
				t = t.split(",");
				t = t.join("");
			}
			
			n = t ? t.indexOf("%") : -1;
			if (n > -1)
			{
				t = t.substring(0, n) + t.substring(n + 1);
			}
	
			r = Number(t);
		}
		else
		{
			r = !cell.code ? null : Number(cell.code)
		}
	
		return r;
	},

	getSep: function() {
		var sep = this.chart_option.xaxissep || ig$.chart_separator || IG$._separator;
		sep = sep == "nl" ? "\n" : sep;
		return sep;
	},

	getBandValue: function(mresult, v, isxaxis) {
		var me = this,
			r,
			fs,
			n1, n2,
			ms,
			seq,
			i, j, c,
			nrow, ncol, mdata,
			fval;
		
		if (mresult)
		{
			if (isxaxis)
			{
				fval = Number(v);
				
				r = {
					value: fval
				};
				
				mdata = mresult._tabledata;
				ncol = mresult.colfix;
				nrow = mresult.rowfix;
				
				if (isNaN(fval))
				{
					for (i=0; i < mdata.length; i++)
					{
						for (j=0; j < ncol; j++)
						{
							c = (j == 0) ? mdata[i][j].text : c + " " + mdata[i][j].text; 
						}
						
						if (v == c)
						{
							fval = i - 1;
							break;
						}
					}
					
					r = {
						value: fval,
						code: v
					};
				}
				else
				{
					if (mdata.length > fval + nrow && mdata[fval + nrow])
					{
						for (i=0; i < ncol; i++)
						{
							r.code = (i == 0) ? mdata[fval + nrow][i].text : r.code + " " + mdata[fval + nrow][i].text;
						}
					}
				}
				
				return r;
			}
			else
			{
				fs = mresult.statistics;
				
				n1 = v.indexOf("{");
				n2 = v.indexOf("}");
				
				while (n1 > -1 && n2 > n1)
				{
					ms = v.substring(n1+1, n2);
					seq = -1;
					
					if (ms.indexOf(":") > -1)
					{
						seq = parseInt(ms.substring(ms.indexOf(":") + 1));
						ms = ms.substring(0, ms.indexOf(":"));
					}
					
					if (seq > -1)
					{
						ms = fs[seq][ms.toLowerCase()];
					}
					else
					{
						ms = ms.toLowerCase();
						fval = null;
						for (i=0; i < fs.length; i++)
						{
							switch(ms)
							{
							case "average":
								fval = (i == 0) ? Number(fs[i].average) : fval + Number(fs[i].average);
								break;
							case "min":
								fval = (i == 0) ? Number(fs[i].min) : Math.min(fval, Number(fs[i].min));
								break;
							case "max":
								fval = (i == 0) ? Number(fs[i].max) : Math.max(fval, Number(fs[i].max));
								break;
							}
						}
						
						if (ms == "average" && fs.length > 0)
						{
							fval = fval / fs.length;
						}
						
						ms = fval;
					}
					
					v = ms + v.substring(n2+1);
					n1 = v.indexOf("{");
					n2 = v.indexOf("}");
				}
			}
		}
		
		if (v.indexOf("/") > -1 || v.indexOf("*") > -1 || v.indexOf("-") > -1 || v.indexOf("+") > -1)
		{
			v = eval(v);
		}
		
		r = {
			value: Number(v)
		};
		
		return r;
	},

	measureTextSize: function(size, text) {
		var me = this,
			cobj = {
				fontSize: size
			},
			s = {};
			
		if (!me.measurediv)
		{
			me.measurediv = $('<div class="m-datagrid-cell-measure"></div>')
				.appendTo($("body"));
		}
		
		me.measurediv.show();
		me.measurediv.css(cobj);
		me.measurediv.html(text || "&nbsp;");
		
		s.height = IG$.j$ext._h(me.measurediv); // .height();
		s.width = IG$.j$ext._w(me.measurediv); // .width() + 2;
		
		return s;
	},
	
	initComponent: function() {
		var arg = arguments;
		
		
	},
	draw: function(mresult) {
		var me = this,
			def = [];

		me.render(def, mresult);
	},
	updatedisplay: function(w, h) {
		
	},
	render: function(def, mresult) {
	},
	dispose: function() {
	},
	getExportData: function(pobj, callback) {
		callback.execute();
	},

	getRelData: function(mresult, positive, adjnegvalue, relationgroups, range) {
		var me = this,
			i, j,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			title,
			row,
			tn,
			dp = [],
			a, b,
			len, item,
			matrixdata = {nodes: [], links: [], categories: []},
			cvalue,
			mcr = me.sheetoption.model.chart_option,
			sep = (mcr ? mcr.xaxissep : null) || ig$.chart_separator || IG$._separator;
			
		sep = sep == "nl" ? "\n" : sep;

		if (relationgroups)
		{
			for (i=0; i < relationgroups.length; i++)
			{
				matrixdata.categories.push({name: relationgroups[i]});
			}
		}
	
		for (i=fc; i < data[0].length; i++)
		{
			title = "";
	
			for (j=0; j < fr; j++)
			{
				title = (j==0 ? data[j][i].text : title + sep + data[j][i].text);
			}
			matrixdata.nodes.push({nodeName: title, name: title, group: (relationgroups && relationgroups.length > i - fc && relationgroups[i - fc] != "") ? parseInt(relationgroups[i - fc]) : i});
		}
	
		len = matrixdata.nodes.length;
	
		for (i=fr; i < data.length; i++)
		{
			row = [];
			for (j=fc; j < data[i].length; j++)
			{
				tn = Number(data[i][j].code) || 0;
				row.push(tn);
			}
			dp.push(row);
		}
	
		for (a = 0; a < len; a++)
		{
			for (b = 0; b < a + 1;  b++)
			{
				if(a != b)
				{
					item = {source: a, target: b};
					cvalue = me.corRelCoefficient(dp, a, b);
	
					if (range.s <= cvalue && cvalue <= range.t)
					{
						item.value = cvalue;
						item.value = (adjnegvalue == true) ? (cvalue + 1) * 10 : cvalue * 10;
						if (positive == 1)
						{
							if (cvalue > 0)
							{
								matrixdata.links.push(item);
							}
						}
						else if (positive == 0)
						{
							if (cvalue < 0)
							{
								matrixdata.links.push(item);
							}
						}
						else
						{
							matrixdata.links.push(item);
						}
					}
				}
			}
		}
	
		return matrixdata;
	},

	corRelCoefficient: function(collection, a, b) {
		var len = collection.length,
			xTotal = 0,
			yTotal = 0,
			xSquaredTotal = 0,
			ySquaredTotal = 0,
			xYTotal = 0,
			o,
			i;
	
		for (i=0; i < collection.length; i++)
		{
			o = collection[i];
			var xValue = o[a];
			var yValue = o[b];
			xTotal += xValue;
			yTotal += yValue;
			xSquaredTotal += Math.pow(xValue,2);
			ySquaredTotal += Math.pow(yValue,2);
			xYTotal += xValue * yValue;
		}
		var top = (len * xYTotal) - (xTotal * yTotal);
		var bottomLeft = Math.sqrt( (len * xSquaredTotal) - Math.pow(xTotal,2) );
		var bottomRight = Math.sqrt( (len * ySquaredTotal) - Math.pow(yTotal,2) );
		return top/(bottomLeft * bottomRight);
	}
};