IG$.chartPlotbandObject = function(bnode) {
	this._content = bnode || {};
}

IG$.chartPlotbandObject.prototype = {
	getRecords: function(rec) {
		var me = this,
			i,
			vkey,
			vval;
			
		$.each(rec.data, function(vkey, vval) {
			if (vkey != "id" && vkey != "selected")
			{
				me._content[vkey] = vval;
			}
		});
		
		me.value_desc = me.getValDesc();
	},
	
	updateRecords: function(rec) {
		var me = this,
			_content = me._content,
			i,
			vkey,
			vval;
			
		$.each(_content, function(vkey, vval) {
			if (vkey != "id" && vkey != "selected")
			{
				rec.set(vkey, vval);
			}
		});
		me.value_desc = me.getValDesc();
		rec.set("value_desc", me.value_desc);
	},
	
	getValDesc: function() {
		var bp = this._content,
			r;
		
		if (bp.type == "curvefit")
		{
			r = "Curve fit (" + (bp.rtype || "") + ")";
		}
		else if (bp.type == "band")
		{
			r = (bp.value_1 || "No value") + " ~ " + (bp.value_2 || "No value");
		}
		else
		{
			r = bp.value_1 || "No value";
		}
		return r;
	},
	
	_v1: function(v, isxaxis) {
		
	}
};

