	changeDrillChartType: function(menu) {
		var me = this,
			drilldepth = menu.drilldepth,
			subtype = menu.subtype,
			drillcharttype,
			i,
			_chartview = (me._chartPnls.length > drilldepth) ? me._chartPnls[drilldepth]._chartview : null;
			
		if (_chartview)
		{
			drillcharttype = _chartview.sheetoption.model.chart_option.drillcharttype = _chartview.sheetoption.model.chart_option.drillcharttype || [];
			
			for (i=0; i < drilldepth + 1; i++)
			{
				if (drilldepth.length > i)
				{
					if (drilldepth == i)
					{
						drillcharttype[i] = subtype;
					}
				}
				else
				{
					if (drilldepth == i)
					{
						drillcharttype.push(subtype);
					}
					else
					{
						drillcharttype.push("");
					}
				}
			} 
			me.drawChartCtrl(_chartview);
		}
	},
	
