	curveFit: function(mc, cf, charttype, view) {
		var me = this,
			olapset = me.olapset,
			chartoption = me.sheetoption ? me.sheetoption.model.chart_option : null,
			mb = {
				charttype: (chartoption ? chartoption.subtype : "column") || "",
				bands: []
			},
			i;
			
		for (i=0; i < cf.length; i++)
		{
			mb.bands.push(cf[i]);
		}
			
		if (olapset)
		{
			var req = new IG$._rpc$();
			req.init(me,
				{
					ack: "olapservice",
					payload: {
						uid: olapset.uid,
						jobid: olapset.jobid,
						option: 'curvefit'
					},
					mbody: mb,
					meta_type: "bands"
				}, me, function(jdoc) {
					var me = this,
						tnode = jdoc ? jdoc.bands : null,
						i;
						
					if (tnode)
					{
						for (i=0; i < tnode.length; i++)
						{
							me.drawBand(mc, tnode[i], mb, view);
						}
					}	
				}
			);
			req.send();
		}
	},
	
	drawBand: function(mc, tnode, charttype, view) {
		var me = this,
			series = tnode.series,
			aseries = tnode.all_series,
			bconf = tnode.config,
			fhtml = view._bandFormula,
			showfitexp = bconf.showfitexp;
		
		showfitexp != false && fhtml.show();

		me._frstband = true;
		
		$.each([series, aseries], function(k, mnodes) {
			if (mnodes)
			{
				var ul;
				
				ul = $("<ul></ul>").appendTo(fhtml);
				
				// for (i=0; i < mnodes.length; i++)
				$.each(mnodes, function(r, mnode) {
					var i, j,
						xmin,
						xmax,
						cfit,
						rtype,
						formula,
						formula_html,
						params,
						pnode,
						pnodes,
						tval,
						bname,
						sname,
						pdiv,
						rs, rsadj,
						rsdesc = "",
						stnode,
						cseries;
				
					xmin = mnode.xmin;
					xmax = mnode.xmax;
					
					xmin = xmin ? Number(xmin) : null;
					xmax = xmax ? Number(xmax) : null;
					
					cfit = mnode.curvefit;
					rtype = mnode.rtype;
					formula = mnode.formula;
					formula_html = mnode.formula_html;
					
					rs = mnode.r_square;
					rsadj = mnode.r_square_adj;
					
					if (rs || rsadj)
					{
						rsdesc = (rs ? "<br /><span class='igc-cfit-rst'>R sqaure : </span><span class='igc-cfig-rs'>" + rs + "</span>" : "")
							+ (rsadj ? "<br /><span class='igc-cfit-rst'>R sqaure adj: </span><span class='igc-cfig-rs'>" + rsadj + "</span>" : "");
					}
					
					bname = bconf.name;
					sname = k == 1 ? "(ALL)" : (mnode.seriename || "");
					
					pdiv = $("<li class='igc-cfit-leg-item'><span class='igc-cfit-bname'>" + (bname ? bname + ": " : "") + "</span><span class='igc-cfit-seriename'>" + sname + "</span><br /><span class='igc-cfit-fm'>" + (formula_html || formula) + "</span>" + rsdesc + "</li>").appendTo(ul);
					
					params = [];
					
					pnode = mnode.parameters;
					
					for (j=0; j < pnode.length; j++)
					{
						tval = pnode[j];
						params.push(Number(tval));
					}
					
					cseries = me.drawBandSeries(mc, rtype, formula_html || formula, params, charttype, xmin, xmax, bconf);
					
					pdiv.bind("click", function(ev) {
						var m = $(this);
						
						if (me.__sel_s)
						{
							me.__sel_s.pdiv.removeClass("igc-cfit-sel");
							me.__sel_s.series.update({
								lineWidth: 2
							}, true);
						}
						if (cseries)
						{
							m.addClass("igc-cfit-sel");
							
							cseries.update({
								lineWidth: 6
							}, true);
							
							me.__sel_s = {
								pdiv: m,
								series: cseries
							};
						}
					});
				});
			}
		});
	},
	
