	doClusterLayout: function(refreshdata) {
		var i,
			me = this,
			chart = me.body.dom,
			titems,
			cols,
			rows,
			dwidth,
			dheight,
			w = me.getWidth(),
			h = me.getHeight(), //  - 32 - 40,
			collapsedcnt = 0,
			ncnt = 0,
			hasMax = false,
			cpanel = $(me.containerpnl.body.dom);
		
		titems = 0;
		w = me.containerpnl.getWidth();
		h = me.containerpnl.getHeight();
		
		for (i=0; i < me._chartPnls.length; i++)
		{
			if (me._chartPnls[i]._collapse == "maximize")
			{
				hasMax = true;
				// me._chartPnls[i].setVisible(((hasMax && me._chartPnls[i].collapse == "maximize") || hasMax == false) ? true : false);
				me.cslicemin.setVisible(false);
			}
		}
		
		if (hasMax == false && me.cslicemin)
		{
			me.cslicemin.setVisible(true);
			me.cslicemin.removeAll();
		}
		
		$.each(me._chartPnls, function(i, itemobj) // for (i=0; i < me._chartPnls.length; i++)
		{
			// var itemobj = me._chartPnls[i];
			if (itemobj._collapse == "collapsed")
			{
				itemobj.setVisible(false);
				var btn = new $s.button({
					xtype: "button",
					width: 120,
					text: itemobj.title,
					handler: function() {
						itemobj._collapse = "normal";
						me.doClusterLayout();
					}
				});
				me.cslicemin.add(btn);
				// me.cslicemin.add(itemobj);
			}
			else if (itemobj._collapse == "maximize")
			{
				itemobj.setVisible(true);
				// me.containerpnl.add(itemobj);
				itemobj.setPosition(0, 0);
				itemobj.setSize(w, h);
			}
			else if (itemobj._collapse == "normal")
			{
				itemobj.setVisible(hasMax == true ? false : true);
				// me.containerpnl.add(itemobj);
				titems++;
			}
		});
		
		if (hasMax == false)
		{
			cols = (titems < 3) ? titems : 
				(titems < 6) ? titems / 2 :
				(titems < 12) ? titems / 3 :
				(titems < 20) ? titems / 4 :
				titems / 4;
			
			cols = Math.floor(cols);
			rows = Math.ceil(titems / cols);
			dheight = (h - me.cslicemin.getHeight()) / rows;
			
			if (dheight < 200)
			{
				dwidth = (w - 18) / cols;
				dheight = 200;
				cpanel.css({overflowY: "scroll"});
				// me.cslicecontainer.css({overflowY: "scroll"});
			}
			else
			{
				dwidth = w / cols;
				// me.containerpnl.setAutoScroll(false);
				cpanel.scrollTop(0);
				cpanel.css({overflowY: "hidden"});
				// me.cslicecontainer.css({overflowY: "hidden"});
			}
			
			$.each(me._chartPnls, function(i, pnl) {
				var mc,
					mr,
					chartview;
				
				if (pnl._collapse == "normal")
				{
					mc = dwidth * (ncnt % cols);
					mr = dheight * (Math.floor(ncnt / cols) % rows);
					me._chartPnls[i].setPosition(mc, mr);
					me._chartPnls[i].setSize(dwidth, dheight);
					ncnt++;
				}
				else
				{
					me._chartPnls[i].setPosition(collapsedcnt * 100, 4);
					me._chartPnls[i].setSize(100, 30);
					collapsedcnt++;
				}
				
				if (refreshdata == true)
				{
					chartview = me._chartPnls[i]._chartview;
					me.drawChartCtrl(chartview);
				}
			});
		}
		else
		{
			cpanel.scrollTop(0);
			cpanel.css({overflowY: "hidden"});
		}
	},
	
	layoutChartPnls: function(refreshdata, ispageview) {
		var me = this,
			mcr = me.sheetoption ? me.sheetoption.model.chart_option : null;
			
		if (!mcr)
			return;
		
		if (refreshdata == true && mcr.bands && mcr.bands.length && me.mresults && me.mresults.results.length)
		{
			var results = me.mresults.results[0],
				req = new IG$._rpc$();
				
			req.init(me, {
				ack: "olapservice",
				payload: { 
					option: "statistics",
					active: "" + me.sheetoption.si,
					jobid: me.mresults.jobid
				},
				mbody: {}
			}, me, function(sdoc) {
				results.statistics = sdoc.statistics;
				me.internalLayoutChartPnls(refreshdata, ispageview);
			});
			req.send();
		}
		else
		{
			me.internalLayoutChartPnls(refreshdata, ispageview);
		}
	},
	
	internalLayoutChartPnls: function(refreshdata, ispageview) {
		var i,
			me = this,
			titems,
			dwidth,
			dheight,
			drillviewmode,
			w, h,
			mc, mr,
			cpanel = $(me.containerpnl.body.dom);
					
		if (me._chartPnls.length == 0)
			return;
		
		cpanel.scrollTop(0);
		cpanel.css({overflowY: "hidden"});
		
		w = me.getWidth() || me.width,
		h = me.getHeight() || me.height;
		
		for (i=me.drilldepth + 1; i < me._chartPnls.length; i++)
		{
			me._chartPnls[i].setVisible(false);
		}
		
		titems = Math.min(me._chartPnls.length, me.drilldepth + 1);
		drillviewmode = me.sheetoption.model.chart_option.drillviewmode;
		
		/*public static var LAYOUT_NORMAL:int = 0;
		public static var LAYOUT_POPUP:int = 1;
		public static var LAYOUT_CASCADE:int = 2;
		public static var LAYOUT_HORIZONTAL:int = 3;
		public static var LAYOUT_VERTICAL:int = 4; */
		
		dwidth = (drillviewmode == 3) ? w / titems : w;
		dheight = (drillviewmode == 4) ? h / titems : h;
		
		for (i=0; i < titems; i++)
		{
			mc = (drillviewmode == 3) ? dwidth * i : 0;
			mr = (drillviewmode == 4) ? dheight * i : 0;
			
			var pw = me._chartPnls[i].pw,
				ph = me._chartPnls[i].ph,
				px = me._chartPnls[i].px,
				py = me._chartPnls[i].py;
			
			me._chartPnls[i].setVisible((drillviewmode == 0 && i < titems - 1 ? false : true));
			if (pw != dwidth || ph != dheight || px != mc || py != mr)
			{
				me._chartPnls[i].setPosition(mc, mr);
				me._chartPnls[i].setSize(dwidth, dheight);
				
				me._chartPnls[i].pw = dwidth;
				me._chartPnls[i].ph = dheight;
				me._chartPnls[i].px = mc;
				me._chartPnls[i].py = mr;
			}
			
			if (refreshdata == true)
			{
				me.drawChartCtrl(me._chartPnls[i]._chartview, ispageview);
			}
			else
			{
				if (pw != dwidth || ph != dheight || i > 0)
				{
					me._chartPnls[i]._chartview.invalidateSize(dwidth, dheight);
				}
			}
		}
	},
	
