IG$.cVis.protovis = $s.extend(IG$.cVis.base, {
	charttype: "protovis",
	subtype: null,

	init_draw: function(mresult) {
		var i,
			j,
			me = this,
			mcr = me.sheetoption ? me.sheetoption.model.chart_option : null,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			tc = (data.length > 0) ? data[0].length : 0,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn;
	
		me.drawmode = "protovis";
	
		me.mresult = mresult;
		
		mcr.settings = mcr.settings || {};
	
		var jdom = $(me.container),
			w = IG$.j$ext._w(jdom),
			h = IG$.j$ext._h(jdom),
			sep = (mcr ? mcr.xaxissep : null) || ig$.chart_separator || IG$._separator;
			
		sep = sep == "nl" ? "\n" : sep;
		
		if (me.vis)
		{
			$(me.container).empty();
			me.vis = null;
		}
	},

    dynLoad: function(f) {
		var me = this,
			scmap = ig$.bootconfig.scmap,
			scripts = [],
			i,
			isie8 = false,
			browser = window.bowser,
			_dynloaded = me._dynloaded;
		
		me._trycnt = me._trycnt || 0;
		me._trycnt++;
		
		if (me._trycnt > 5)
		{
			IG$.ShowError(IRm$.r1("E_CHART_LIB_LOADING")); // "Error on chart library loading!");
			return;
		}
		
		isie8  = (browser.msie && browser.version < 9) ? true : false;
		
		if (_dynloaded)
		{
			setTimeout(function() {
				f.call(me);
			}, 10);
			return;
		}
		
		$.each(
			[
				[
					isie8 ? "./js/excanvas.js" : null,
					(!window.pv ? "./js/protovis-d3.3.js" : null),
					isie8 ? null : (!window.d3 ? "./js/d3.js" : null),
					!window.d3 || (window.d3 && !window.d3.tip) ? "./js/d3.tip.js" : null,
					!window.d3 || (window.d3 && !window.d3.geo) ? "./js/d3.geo.js" : null,
					!window.Raphael || (window.Raphael && !window.Raphael.g) ? "./js/g.raphael.js" : null,
					!window.Raphael || (window.Raphael && !window.Raphael.fn.dotchart) ? "./js/g.dot.js" : null
				],
				scmap.igc6,
				scmap.igco,
				scmap.igcb
			], function(n, ar) {
				var i;
				for (i=0; i < ar.length; i++)
				{
					ar[i] && scripts.push(ar[i]);
				}
			}
		);
				
		IG$.getScriptCache(scripts, new IG$.callBackObj(me, function() {
			var me = this;
			me._dynloaded = 1;
			f.call(me);
		}));
	},

    draw: function(mresult) {
        var me = this;
		
		if (me.draw_protovis)
		{
			me.init_draw(mresult);
			me.draw_protovis.apply(me, [mresult]);
		}
		else
		{
			me.dynLoad(function() {
				var me = this;
				setTimeout(function() {
					me.init_draw(mresult);
					me.draw_protovis && me.draw_protovis.apply(me, [mresult]);
				}, 10);
			});
		}
    },

	updatedisplay: function(w, h) {
		var me = this;
		
		if (me.vis)
		{
			$(me.container).empty();
			me.vis = null;
			
			me.mresult && me.draw(me.mresult);
		}
	},

	dispose: function() {
		var me = this,
			ui = me.chartview;

		if (ui)
		{
			$(ui.container).empty();
			ui.vis = null;
		}

		IG$.cVis.protovis.superclass.dispose.apply(me, arguments);
	},

	getExportData: function(pobj, callback) {
		if (me.vis)
		{
			svgnode = IG$.getFstChld(me.container);

			IG$.XSetAttr(svgnode, "xmlns:xlink", "http://www.w3.org/1999/xlink");
			IG$.XSetAttr(svgnode, "xmlns", "http://www.w3.org/2000/svg");
			IG$.XSetAttr(svgnode, "version", "1.1");

			svg = IG$.toXMLString(svgnode);
			
			pobj.image_type = "svg";
			pobj.image_data = Base64.encode(svg);
		}
		callback.execute(pobj);
	}
});