IG$.filterMainEditor = $s.extend($s.panel, {
	layout: "fit",
	
	busy: false,
	
	reportoption: null,
	sheetoption: null,
	
	confirmFilterSetting: function() {
		var me = this,
			root = me.rootnode,
			i;
			
		if (me.sheetoption)
		{
			var sheetoption = me.sheetoption,
				model = sheetoption.model,
				ofilter = model.filter,
				ohavingfilter = model.havingfilter;
				
			model.filter = {
				ftype: "group",
				children: []
			};
			model.havingfilter = {
				ftype: "group",
				children: []
			}
			
			if (ofilter || ohavingfilter)
			{
				if (ofilter)
				{
					model.filter.auth = ofilter.auth;
					model.filter.active = ofilter.active;
				}
				
				if (ohavingfilter)
				{
					model.havingfilter.auth = ohavingfilter.auth;
					model.havingfilter.active = ohavingfilter.active;
				}
			}
			
			$.each(root.children, function(i, fitem) {
				var sfilter = null;
				
				if (fitem.condition == "WHERE")
				{
					sfilter = model.filter;
				}
				else if (fitem.condition == "HAVING")
				{
					sfilter = model.havingfilter;
				}
				
				if (fitem.children.length > 0)
				{
					$.each(fitem.children, function(i, cobj) {
						me.updateFilterChanges(sfilter, cobj);
					});
				}
			});
		}
	},
	
	updateFilterChanges: function(ufilter, cnode) {
		var i,
			me = this;
		
		if (cnode.nodetype == "group")
		{
			var tgroup = {
				ftype: "group",
				children: []
			};
			
			tgroup.name = cnode.name;
			tgroup.conjunction = cnode.conjunction;
			ufilter.children.push(tgroup);
			
			if (cnode.children.length)
			{
				$.each(cnode.children, function(i, cobj) {
					me.updateFilterChanges(tgroup, cobj);
				});
			}
		}
		else if (cnode.nodetype == "condition")
		{
			var f = cnode.filternode.model;
			f.ftype = "condition";
			f.conjunction = f.conjunction || "AND";
			ufilter.children.push(f);
		}
	},
	
	getGroupRenderer: function(tEl, fgroup, unode) {
		var btndiv = $("<div class='filterbtn'></div>"),
			me = this, 
			btn1 = $("<div class='filterbtnitem icon-addfilter-group' title='Add SubGroup'>&nbsp;</div>"),
			filterpid = fgroup.pid,
			tb,
			fnamefield = $("<span>" + fgroup.name + "</span>"),
			fnameeditor = $("<input type='text'></input>"),
			ftitle = $("<div class='filter-header'></div>"),
			i, hasgroup = false,
			btn_conjunction,
			cnt;
		
		if (unode.children.length > 0)
		{
			for (i=0; i < unode.children.length; i++)
			{
				if (unode.children[i].nodetype == "group")
				{
					hasgroup = true;
					break;
				}
			}
			
			if (hasgroup)
			{
				fgroup.cblk = $("<div class='filter-condition filter-conjunction'>" + (fgroup.conjunction || "AND") + "</div>").appendTo(unode.htmlgrp);
				
				fgroup.cblk.bind("click", function() {
					if (fgroup.conjunction == "OR")
					{
						fgroup.conjunction = "AND";
					}
					else
					{
						fgroup.conjunction = "OR";
					}
					
					fgroup.cblk.text(fgroup.conjunction);
				});
			}
		}
		
		fgroup.html = $("<div class='filter-block'><div class='filter-block-cnt'></div></div>");
		cnt = $(".filter-block-cnt", fgroup.html);
		fgroup.html.appendTo(unode.htmlgrp);
		cnt.append(ftitle);
		ftitle.append(fnamefield);
		fnameeditor.css({width: 80, display: "none"});
		ftitle.append(fnameeditor);
		
		ftitle.append(btndiv);
		btndiv.append(btn1);
		
		fgroup.html.draggable({
			revert: true,
			handle: ftitle,
			create: function(event, ui) {
				
			},
			drag: function(event, ui) {
				
			},
			start: function(event, ui) {
				
			},
			stop: function(event, ui) {
				
			}
		});
		
		fgroup.fnameeditor = fnameeditor;
		fgroup.fnamefield = fnamefield;
		
		fnamefield.bind("click", function() {
			me.editName(fgroup);
		});
		
		fnameeditor.bind("keypress", function(e) {
			if (e.keyCode == 13)
			{
				me.endEditName(fgroup);
			}
		});
		
		btn1.bind("click", function() {
			if (fgroup.children.length > 0)
			{
				me.appendGroup(tEl, fgroup);
			}
		});
		
		var btn2 = $("<div class='filterbtnitem icon-addfilter-cond' title='Add Condition'>&nbsp;</div>");
		btndiv.append(btn2);
		btn2.bind("click", function() {
			me.appendCondition(tEl, fgroup);
		});
		
		var btn3 = $("<div class='filterbtnitem icon-filter-remove' title='Delete Condition'>&nbsp;</div>");
		btndiv.append(btn3);
		btn3.bind("click", function() {
			me.deleteItem(fgroup, unode);
		});
		
		fgroup.htmlcond = $("<div class='filtercond'></div>");
		tb = $("<ul class='filtergroup'></ul>");
		fgroup.htmlgrp = $("<li></li>").appendTo(tb);
		cnt.append(fgroup.htmlcond);
		cnt.append(tb); // fgroup.htmlgrp);
	},
	
	getCondRenderer: function(tEl, fcond, unode) {
		var me = this,
			btndiv = $("<div class='filterbtn'></div>");
			 
		fcond.html = $("<li></li>");
		unode.htmlcond.append(fcond.html);
		
		fcond.html.append($("<div class='filter-conjunction'></div>"));
		var btnedit = $("<div class='filtereditbtn'>" + fcond.name + "</div>");
		fcond.html.append(btnedit);
		
		var btn_conjunction = $(".filter-conjunction", fcond.html);
		btn_conjunction.text(fcond.filternode.model.conjunction || "AND");
		
		btn_conjunction.bind("click", function() {
			if (fcond.filternode.model.conjunction == "OR")
			{
				fcond.filternode.model.conjunction = "AND";
			}
			else
			{
				fcond.filternode.model.conjunction = "OR";
			}
			
			btn_conjunction.text(fcond.filternode.model.conjunction);
		});
		
		btnedit.draggable({
			containment: tEl,
			helper: "clone",
			create: function(event, ui) {
				
			},
			drag: function(event, ui) {
				
			},
			start: function(event, ui) {
				
			},
			stop: function(event, ui) {
				var tnode,
					pt = [ui.offset.left, ui.offset.top],
					filternode = me.rootnode,
					i;
				
				tnode = me.hitBoundary(filternode, pt);
				
				if (tnode)
				{
					if (tnode.nodetype == "group")
					{
						for (i=0; i < unode.children.length; i++)
						{
							if (unode.children[i] == fcond)
							{
								unode.children.splice(i, 1);
								break;
							}
						}
						
						tnode.children.push(fcond);
						tnode.htmlcond.append(fcond.html);
					}
				}
			}
		});
		
		fcond.deschtml = btnedit;
		
		btnedit.bind("click", function() {
			me.editItem(fcond);
		});
		
		fcond.html.append(btndiv);
		
		var btn3 = $("<div class='filterbtnitem icon-filter-remove' title='Delete Condition'>&nbsp;</div>");
		
		btndiv.append(btn3);
		
		btn3.bind("click", function() {
			me.deleteItem(fcond, unode);
		});
	},
	
	editName: function(item) {
		var me = this,
			editor = item.fnameeditor,
			field = item.fnamefield;
		
		field.css({display: "none"});
		editor[0].value = item.name;
		editor.css({display: "inline", width: IG$.j$ext._w(field) || 100});
	},
	
	endEditName: function(item) {
		var me = this,
			editor = item.fnameeditor,
			field = item.fnamefield,
			fname = editor[0].value;
		
		editor.css({display: "none"});
		// editor[0].text = item.name;
		field.css({display: "inline"});
		item.name = fname;
		field.text(item.name);
		
		me._refreshFilter();
	},
	
	appendGroup: function(tEl, unode) {
		var me = this;
			
		var fgroup = {
			name: "Conditions",
			nodetype: "group",
			unode: unode,
			children: [],
			filternode: null
		};
		
		me.getGroupRenderer(tEl, fgroup, unode);

		unode.children.push(fgroup);
		
		me._refreshFilter();
		
		return fgroup;
	},
	
	appendCondition: function(tEl, unode, targetitem) {
		var me = this,
			filter = new IG$.clFilter(null),
			reportoption = me.reportoption,
			sheetoption = me.sheetoption,
			cubeuid;
		
		if (sheetoption && sheetoption.model && sheetoption.model.cube_object)
		{
			cubeuid = sheetoption.model.cube_object.uid;
		}
		else if (reportoption && reportoption.cube_objects && reportoption.cube_objects.length > 0)
		{
			cubeuid = reportoption.cube_objects[0].uid;
		}
		
		filter.operator = 6;
		
		var pop = new IG$.filterEditor({
			instance: me.instance,
			meta_type: me.meta_type,
			filteritem: filter,
			reportoption: me.reportoption,
			targetitem: targetitem,
			cubeuid: cubeuid,
			callback: new IG$.callBackObj(me, me.rs_appendCondition, [unode, filter, tEl])
		});
		IG$.checkLogin(this, pop);
	},
	
	editItem: function(item) {
		var me = this,
			i,
			pwin,
			cubeuid = me.sheetoption && me.sheetoption.datasource ? me.sheetoption.datasource.uid : null;
			
		if (item)
		{
			pwin = new IG$.filterEditor({
				instance: me.instance,
				meta_type: me.meta_type,
				filteritem: item.filternode,
				reportoption: me.reportoption,
				cubeuid: cubeuid,
				callback: new IG$.callBackObj(me, me.rs_editCondition, [item, item.filternode])
			});
			IG$.checkLogin(this, pwin);
		}
	},
	
	rs_editCondition: function(param) {
		var me = this,
			unode = param[0],
			filter = param[1],
			desc;
		
		if (unode)
		{
			desc = filter.getDesc();
			unode.name = desc;
			
			unode.deschtml.text(unode.name);
		}
		
		me._refreshFilter();
	},
	
	deleteItem: function(item, pitem) {
		var me = this,
			i,
			hasmgroup = 0;
		
		if (item)
		{
			for (i=0; i < pitem.children.length; i++)
			{
				if (pitem.children[i] == item)
				{
					pitem.children.splice(i, 1);
					break;
				}
			}
			
			item.cblk && item.cblk.remove();
			item.cblk = null;
			item.html.remove();
			
			if (pitem.children.length > 0)
			{
				for (i=0; i < pitem.children.length; i++)
				{
					if (pitem.children[i].nodetype == "group")
					{
						if (hasmgroup == 0)
						{
							pitem.children[i].cblk && pitem.children[i].cblk.remove();
							pitem.children[i].cblk = null;
						}
						hasmgroup++;
					}
				}
			}
		}
		
		me._refreshFilter();
	},
	
	rs_appendCondition: function(param) {
		var me = this,
			unode = param[0],
			filter = param[1],
			tEl = param[2];
		
		if (unode)
		{
			var obj = {
				unode: unode,
				name: filter.getDesc(),
				nodetype: "condition",
				filternode: filter
			};
			
			me.getCondRenderer(tEl, obj, unode);
			
			unode.children.push(obj);
		}
		
		me._refreshFilter();
	},
	
	_init: function() {
		var me = this,
			i,
			sheetoption = me.sheetoption,
			model = sheetoption ? sheetoption.model : null;
		
		me.filterview = me.down("[name=filterview]");
		
		// clear all
		var el = $(".igc-filter-el", me.filterview.body.dom);
		$(el).empty();
		
		me.rootnode = {};
		me.rootnode_w = {};
		me.rootnode_h = {};
		
		if (model)
		{
			if (!model.filter)
			{
				model.filter = {
					ftype: "group",
					children: []
				};
			}

			if (!model.havingfilter)
			{
				model.havingfilter = {
					ftype: "group",
					children: []
				};
			}
			
			me.rootnode = {
				name: "Conditions",
				nodetype: "rootgroup",
				children: [
				]
			};
			
			me.rootnode_w = {
				name: "WHERE",
				nodetype: "rootgroup",
				condition: "WHERE",
				children: [
					
				]
			};
			
			me.rootnode_h = {
				name: "HAVING",
				condition: "HAVING",
				nodetype: "rootgroup",
				children: [
					
				]
			};
			
			me.rootnode.children.push(me.rootnode_w);
			me.rootnode.children.push(me.rootnode_h);
			
			$.each(me.rootnode.children, function(i, rootnode) {
				var rnode, t = $("<div class='filter-root'></div>"),
					btndiv = $("<div class='filterbtn'></div>"),
					filter = model.filter,
					havingfilter = model.havingfilter,
					tb,
					i,
					btn = $("<div class='filterbtnitem icon-addfilter-group' title='Add SubGroup'>&nbsp;</div>");
					
				t.appendTo(el);
				rnode = rootnode;
				rnode.html = $("<div class='filtercontainer'><div class='filter-header'><span class='filtertitle'>" + rootnode.name + "</span></div></div>");
				btn.appendTo(btndiv);
				$(".filter-header", rnode.html).append(btndiv);
				tb = $("<ul class='filtergroup'></ul>");
				rnode.htmlgrp = $("<li></li>").appendTo(tb);
				rnode.html.append(tb);
				rnode.html.appendTo(t);
				
				btn.bind("click", function() {
					me.appendGroup(t, rootnode);
				});
				
				if (rootnode.condition == "WHERE")
				{
					if (filter && filter.children && filter.children.length)
					{
						if (filter.children[0].ftype == "condition")
						{
							var fgroup = {
								ftype: "group",
								name: "Conditions",
								active: true,
								children: []
							};
							
							for (i=0; i < filter.children.length; i++)
							{
								fgroup.children.push(filter.children[i]);
							}
							
							filter.children = [fgroup];
						}
						$.each(filter.children, function(i, flt){
							me.makeFilterData(t, rootnode, flt);
						});
					}
				}
				else if (rootnode.condition == "HAVING")
				{
					if (havingfilter && havingfilter.children && havingfilter.children.length)
					{
						if (havingfilter.children[0].ftype == "condition")
						{
							var fgroup = {
								ftype: "group",
								name: "Conditions",
								active: true,
								children: []
							};
							
							for (i=0; i < havingfilter.children.length; i++)
							{
								fgroup.children.push(havingfilter.children[i]);
							}
							
							havingfilter.children = [fgroup];
						}
						$.each(havingfilter.children, function(i, flt){
							me.makeFilterData(t, rootnode, flt);
						});
					}
				}
			});
			
			if (me.targetitem)
			{
				setTimeout(function() {
					me.in$l();
				}, 400);
			}
		}
	},
	
	in$l: function() {
		var me = this,
			filter = me.sheetoption.filter,
			froot = me.rootnode_w,
			tfilter = null,
			targetitem = me.targetitem,
			fg = null;
			
		tfilter = filter.findItem(targetitem.uid);
				
		if (tfilter)
		{
			me.editItem(tfilter.id);
		}
		else
		{
			if (filter.subGroups.length > 0)
			{
				fg = froot.children[0];
			}
			else
			{
				fg = me.appendGroup(me.rootnode_w);
			}
			
			me.appendCondition(fg, targetitem);
		}
		
		me._refreshFilter();
	},
	
	makeFilterData: function(tEl, unode, fnode) {
		var me = this,
			filter,
			obj, i;
		
		if (fnode.children && fnode.children.length > 1)
		{
			unode.htmlgrp.addClass("filter-multi-cond");
		}
		else
		{
			unode.htmlgrp.removeClass("filter-multi-cond");
		}
		
		if (fnode.ftype == "condition")
		{
			filter = new IG$.clFilter(fnode)
			obj = {
				pnode: unode,
				name: filter.getDesc(),
				nodetype: "condition",
				filternode: filter
			};
			
			me.getCondRenderer(tEl, obj, unode);
			unode.htmlcond.append(obj.html);
			unode.children.push(obj);
		}
		else
		{
			obj = {
				name: fnode.name || "SubGroup",
				pnode: unode,
				children: [],
				nodetype: "group",
				filternode: fnode
			};
			
			me.getGroupRenderer(tEl, obj, unode);
			unode.children.push(obj);
			
			if (fnode.children && fnode.children.length)
			{
				$.each (fnode.children, function(i, gobj) {
					me.makeFilterData(tEl, obj, gobj);
				});
			}
		}
		
		me._refreshFilter();
	},
	
	make_dropzone: function(el) {
		var me = this;
		
		me.dropZone = $s.create($s.dropzone, el, {
			ddGroup: "_I$RD_G_",
			
			nodeouttimer: -1,
			
			getTargetFromEvent: function(e) {
				var renderer = el;
				return renderer;
			},
			
			onNodeEnter : function(target, dd, e, data){
				var i,
					dt, dttype,
					hasitem = false,
					accept = false;
					
				if (data.records && data.records.length > 0)
				{
					dt = data.records[0].get("type");
					
					if (dt == "Metric" || dt == "CustomMetric" || dt == "Measure" || dt == "FormulaMeasure")
					{
						accept = true;
					}
				}
								
				this.accept = accept;
			},
			onNodeOut : function(target, dd, e, data){
			},
			onNodeOver : function(target, dd, e, data){
				var dt,
					ret = this.accept == true,
					dt;
				if (this.accept == true)
				{
					if (data.records && data.records.length > 0)
					{
						dt = data.records[0].data;
					}
					else
					{
						dt = data.cellData;
					}
					
					if (e.xy)
					{
						// me.showDropProxy(el, e.xy);
					}
				}
				return ret;
			},
			onNodeDrop : function(target, dd, e, data){
				var dt;
				
				if (this.accept == true)
				{
					if (data.records && data.records.length > 0)
					{
						dt = data.records[0];
						if (e.xy)
						{
							me.processFilterDrop(el, dt, el, e.xy);
						}
					}
					else
					{
						dt = data.cellData;
					}
				}
				
				this.accept = false;
				return true;
			}
		});
	},
	
	hitBoundary: function(node, pt) {
		var thtml,
			toffset,
			i,
			pobj,
			me = this;
		
		for (i=0; i < node.children.length; i++)
		{
			thtml = node.children[i].html;
			toffset = thtml.offset();
			
			if (toffset.left < pt[0] && pt[0] < toffset.left + IG$.j$ext._w(thtml) &&
				toffset.top < pt[1] && pt[1] < toffset.top + IG$.j$ext._h(thtml))
			{
				pobj = node.children[i];
				
				sobj = me.hitBoundary(node.children[i], pt);
				
				if (sobj)
				{
					pobj = sobj;
				}
				break;
			}
		}
		
		return pobj;
	},
	
	processFilterDrop: function(tEl, rec, el, pt) {
		var me = this,
			filternode = me.rootnode,
			tnode, pnode, pc;
		
		tnode = me.hitBoundary(filternode, pt);
		
		if (tnode)
		{
			var dt = {};
			dt.uid = rec.get("uid");
			dt.name = rec.get("name");
			dt.type = rec.get("type");
			dt.contentfullpath = rec.get("contentfullpath");
			dt.itemtype = dt.type;
			
			pnode = tnode.unode;
			
			while (pnode)
			{
				if (pnode.nodetype == "rootgroup")
				{
					pc = pnode.condition;
					break;
				}
				pnode = pnode.unode;
			}
			
			if (dt.type != "Measure" && dt.type != "FormulaMeasure" && pc == "HAVING")
			{
				return;
			}
			
			me.appendCondition(tEl, tnode, dt);
		}
		
		me._refreshFilter();
	},
	
	render: function() {
		var me = this,
			filterview = me.down("[name=filterview]"),
			el = filterview.body.dom;
		
		me.make_dropzone(el);
	},
	
	set_count: function(counts) {
		var me = this;
		
		me.count_seq = 0;
		
		$.each(me.rootnode.children, function(i, rootnode) {
			if (rootnode.condition == "WHERE")
			{
				me.update_count(rootnode, counts);
			}
		});
	},
	
	update_count: function(rnodes, counts) {
		var i,
			tnode,
			sc;
		
		for (i=0; i < rnodes.length; i++)
		{
			tnode = rnodes[i];
			
			if (tnode.nodetype == "group")
			{
				sc = counts.length > me.count_seq ? counts[me.count_seq] : -1;
				
				me.count_seq++;
				if (tnode.children && tnode.children.length)
				{
					me.update_count(tnode.children, counts);
				}
			}
		}
	},
	
	_refreshFilter: function() {
		var me = this,
			rootnode = me.rootnode;
		
		if (!rootnode)
			return;
		
		rootnode.children.length > 0 && me._refFltSec(rootnode.children[0], 0);
		rootnode.children.length > 1 && me._refFltSec(rootnode.children[1], 0);
	},
	
	_refFltSec: function(tnode, level) {
		var me = this,
			clen;
			
		if (tnode.children && tnode.children.length)
		{
			clen = tnode.children.length;
			
			$.each(tnode.children, function(i, cobj) {
				var bconjunction = 0,
					btn_conjunction = $(".filter-conjunction", cobj.html);
				
				if (clen > 1 && i > 0)
				{
					bconjunction = 1;
				}
				
				btn_conjunction[bconjunction ? "show" : "hide"]();
				me._refFltSec(cobj, level+1);
			});
		}
	},
	
	initComponent : function() {
		$s.apply(this, {
			items: [
				{
					html: "<div class='igc-filter-el'></div>",
					name: "filterview",
					flex: 1,
					autoScroll: true
				}
			],
			
			listeners: {
				afterrender: function() {
					this.render();
				},
				resize: function() {
				}
			}
		});
		
		IG$.filterMainEditor.superclass.initComponent.apply(this, arguments);
	}
});

IG$.filterEditorWindow = $s.extend($s.window, {
	// title: "Filter",
	modal: true,

	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 500,
	height: 400,
	
	confirmFilterSetting: function() {
		var me = this;
		
		me.mainpanel.confirmFilterSetting();
		me.callback && me.callback.execute(me.sheetoption);
		me.close();
	},
	
	initComponent : function() {
		var me = this;
		
		me.title = IRm$.r1("L_FILTER");
		
		me.mainpanel = new IG$.filterMainEditor({
			instance: me.instance,
			reportoption: me.reportoption,
			sheetoption: me.sheetoption,
			targetitem: me.targetitem
		});
		
		$s.apply(me, {
			
			items: [
				this.mainpanel
			],
			buttons:[

				"->",
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this.confirmFilterSetting();
					},
					scope: this
				}, {
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(tobj) {
					me.mainpanel._init();
				}
			}
		});
		
		IG$.filterEditorWindow.superclass.initComponent.apply(this, arguments);
	}
});