/***********************************************************************
 * AppPageControl: Panel 
 */
IG$.ctrlPanel = IG$.extend(IG$.ctrlBase, {
	type: "panel",
	iscontainer: true,
	initComponent: function() {
		var me = this,
			ptemplate;
		
		me.titleheight = 0;
		
		me.p.push(
			{name: "title", type: "property", datatype: "string"},
			{name: "minheight", type: "property", datatype: "number"},
			{name: "gap", type: "property", datatype: "number"},
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "align", type: "property", datatype: "string", value: "",
				"enum": [
					{name: "none", value: ""},
					{name: "left", value: "left"},
					{name: "center", value: "center"},
					{name: "right", value: "right"}
				]
			},
			{name: "collapsible", type: "property", datatype: "boolean"},
			{name: "scroll", type: "property", datatype: "string", "enum": [
					{name: "none", value: "none"},
					{name: "auto", value: "auto"},
					{name: "show", value: "show"}
				]
			}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	updateProperty: function(kname, value) {
		var me = this,
			validate = 0;
		
		switch (kname)
		{
		case "title":
			me.p_html_t[value ? "show" : "hide"]();
			me.p_html_title.html(value || "");
			break;
		case "layout":
			validate = 1;
			break;
		case "gap":
		case "padding":
		case "align":
			validate = 1;
			break;
		case "minheight":
			me.el$.css({minHeight: value ? "" + value + "px" : "initial"});
			break;
		}
		
		this.updateLayout();
	},
	
	initDrawing: function () {
		var me = this,
			ptemplate;

		ptemplate = [
			'<div class="ig-ds-panel">',
				'<div class="ig-ds-title"><span id="ig-ds-title-text"></span></div>',
				'<div class="ig-ds-body">',
				'</div>',
			'</div>'
		];
		
		me.pdiv$ = $(ptemplate.join("")).appendTo(me.el$);
		me.p_html_t = $(".ig-ds-title", me.pdiv$);
		me.p_html_title = $("#ig-ds-title-text", me.pdiv$);
		me.p_region = $(".ig-ds-body", me.pdiv$);
		
		me.tl$.hide();
		// IG$.setScrRect(me.p_region);
		me.superclass.prototype.initDrawing.call(me);
	},
	
	invalidate: function () {
	},
	
	updateLayout: function() {
	},
	
	getContainer: function() {
		return this.p_region;
	}
});

IG$.controls.panel = new IG$.ctrlPanel({}, null);







