/***********************************************************************
 * AppPageControl: PivotReport 
 */
 IG$.ctrlPivotReport = IG$.extend(IG$.ctrlBase, {
	type: "olapreport",
	initComponent: function() {
		var me = this;
		
		me.canvas = null;
		me.viewer = null;
		me.options = null;
		me.loading = null;
		me.zoom = false;
		me.sheetindex = 0;
		
		me.hidetoolbar = false;
		me.hidestatusbar = false;
		
		me.p.push(
			{name: "draw", type: "property", datatype: "string"},
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "hidetoolbar", type: "property", datatype: "boolean", vmode: 1, value: true},
			{name: "hidestatusbar", type: "property", datatype: "boolean", vmode: 1, value: true},
			{name: "execute_completed", type: "event"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	onClickMagHandler: function (e) {
		var sender = e.data.sender;
		sender.processEvent("magnifire", sender);
	},
	
	initDrawing: function () {
		var me = this;
		
		if (!me.viewer)
		{
			me.viewer = new IG$.ReportView({
				instance: me.instance,
				renderTo: me.el$,
				autofit: true,
				move: false,
				uid: me.uid,
				header: false,
				$init_block_run: true, 
				collapsible: false,
				floatable: false,
				vmode: 1,
				title: 0,
				closeAction: "destroy",
				$openmode: "dashboard"
			});

			me.viewer.on("_lc0", function() {
				void 0;
				me._viewer_loaded = true;
				me._process_nego();
			});
			
			me.viewer.on("afterrender", function(tobj) {
				me.updateProperty("hidetoolbar");
				me.updateProperty("hidestatusbar");
			}, me);
		}
		me.tl$.hide();
		me.__pcinit();
	},
	
	clear: function() {
		var me = this,
			viewer = me.viewer;
			
		viewer && viewer.clearResult();
	},
	
	updateProperty: function(kname) {
		var me = this,
			viewer = me.viewer,
			v = this.property[kname];
		
		if (!viewer)
			return;
			
		switch (kname)
		{
		case "hidetoolbar":
			viewer.hiddentoolbar = v;
			viewer && viewer._tbar && viewer._tbar.setVisible(v ? false : true);
			break;
		case "hidestatusbar":
			viewer.hiddenstatusbar = v;
			viewer && viewer.down("[name=_1]") && viewer.down("[name=_1]").setVisible(v ? false : true);
			break;
		}
	},
	
	invalidate: function () {
		var viewer = this.viewer,
			dzone = viewer.dzone,
			ex = viewer.$ex;

		viewer._adjust(ex, true); //  && viewer.$ex.adjust();
		// viewer.fireEvent("resize", viewer, viewer.$ex.$width, viewer.$ex.$height);
		// dzone && dzone.updateDisplay(true);
		viewer.chlidProcessEvents(viewer, ex.$width, ex.$height, ex.$width, ex.$height, {
			name: "resize",
			_stopPropagation: false,
			_preventDefault: false,
			owner: viewer,
			down: true
		});
	},
	
	getSelectionData: function(itemname) {
		return null;
	},
	
	eRun: function(cback, filters) {
		var me = this,
			viewer = me.viewer,
			pdb = me.ctrl.parentcontrol;
		
		viewer.execallback = new IG$.callBackObj(me, function(jdoc, iserror) {
			var me = this;
			if (iserror != true)
			{
				if (me.ctrl.actionlist)
				{
					me.triggerEvent("execute_completed", {
						ctrl: me.ctrl,
						ptr: me,
						event: "execute_completed"
					});
					/*
					me.ctrl.owner.executeAction(me.ctrl.actionlist["execute_completed"], {
						ctrl: me.ctrl,
						ptr: me,
						event: "execute_completed"
					});
					*/
				}
			}

			viewer.execallback = null;
			cback && cback.execute(iserror);
		})// cback;
		
		if (viewer.uid != me.uid)
		{
			viewer.uid = me.uid;
			viewer.__loaded = false;
			viewer.init_f(true);
		}
		
		viewer._dboardCallback = null;
		
		if (viewer.__loaded)
		{
			viewer.$init_block_run = false;
			viewer.toolbarHandler("cmd_run", null, null, filters);
		}
		else
		{
			viewer._dboardCallback = new IG$.callBackObj(me, function() {
				viewer.toolbarHandler("cmd_run", null, null, filters);
			});
		}
	},
	
	parseFilter: function(node, filter) {
		var me = this;
		
		if (node)
		{
			var fglist = IG$.XGetChildNodes(node, "FilterGroup"),
				i;

			if (fglist && fglist.length > 0)
			{
				for (i=0; i < fglist.length; i++)
				{
					var tgroup = new IG$.clFilterGroup();
					tgroup.name = IG$.XGetAttr(fglist[i], "name"); 
					filter.subGroups.push(tgroup);
					me.parseSubFilter(fglist[i], tgroup);
				}
			}
		}
	},
	parseSubFilter: function(fgnode, ugroup) {
		var i, j,
			group,
			sfg,
			me = this;
		
		sfg = IG$.XGetChildNodes(fgnode);
		
		if (sfg && sfg.length > 0)
		{
			for (j=0; j < sfg.length; j++)
			{
				if (IG$.XGetNodeName(sfg[j]) == "FilterGroup")
				{
					var group = new IG$.clFilterGroup();
					group.name = IG$.XGetAttr(sfg[j], "name"); 
					me.parseSubFilter(sfg[j], group);
					ugroup.subGroups.push(group);
				}
				else
				{
					ugroup.subConditions.push(new IG$.clFilter(sfg[j]));
				}
			}
		}
	},
	
	runReport: function(jdoc) {
		var me = this;
		me.viewer.$init_block_run = false;
		me.viewer.rs_loadContent(jdoc);
	},
	
	applyApplication: function () {
		var me = this;
		
		if (me.applicationItem)
		{
			me.uid = me.applicationItem.uid;
			
			if (!me.dsmode && me.viewer)
			{
				me.viewer.uid = me.uid;
				me.viewer.init_f(true);
			}
		}
	},
		
	negoFilter: function(filterctrl, docid, callback) {
		var me = this;
		
		me._filter_nego = me._filter_nego || [];

		me._filter_nego.push({
			filterctrl: filterctrl,
			docid: docid,
			callback: callback
		});

		me._process_nego();
	},

	_process_nego: function() {
		var me = this,
			_viewer_loaded = me._viewer_loaded,
			_filter_nego = me._filter_nego;

		if (!_viewer_loaded)
			return;

		if (_filter_nego && _filter_nego.length)
		{
			while (_filter_nego.length)
			{
				var nfilter = _filter_nego.shift();
				var filterctrl = nfilter.filterctrl,
					docid = nfilter.docid,
					fctrl = filterctrl.viewer,
					ubody;
					
				ubody = me.viewer.dzone ? me.viewer.dzone.getBox(docid) : null;
				
				if (ubody)
				{
					filterctrl.viewer = ubody.viewer;
					ubody.hidden = true;

					nfilter.callback.execute({ubody: ubody, report: me, reportctrl: me.viewer});
				}
			}
		}
	},

	destroy: function() {
		var me = this;
		
		if (me.viewer && me.viewer.close)
		{
			me.viewer.close();
		}
	}
});

IG$.controls.olapreport = new IG$.ctrlPivotReport({}, null);