

/***********************************************************************
 * AppPageControl: Dashboard 
 */
 IG$.ctrlDashboardPanel = IG$.extend(IG$.ctrlBase, {
	type: "dashboard",
	initComponent: function() {
		var me = this;

		me._viewerRendered = false;
		me.p.push(
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},

	invalidate: function () {
		var me = this,
			viewer = me.viewer;
			
		viewer && viewer.$ex.adjust();
	},

	initDrawing: function () {
		var me = this;
		
		if (!me.viewer)
		{
			me.viewer = new IG$.DashboardView({
				instance: me.instance,
				uid: null,
				autofit: true,
				header: false,
				move: false,
				renderTo: me.el$,
				floatable: false,
				closeAction: "destroy",
				title: 0,
				uid: me.uid,
				collapsible: false,
				header: false,
				dsmode: 1,
				border: 0,
				sm: 0
			});

			me.viewer.on("afterrender", function(tobj) {
				me._viewerRendered = true;
			});
		}
		
		me.tl$.hide();
		me.__pcinit();
	},

	updateProperty: function(kname, value) {
		var me = this;
		
		switch(kname)
		{
		case "report_control":
			break;
		}
	},

	updateLayout: function() {
	},
	destroy: function() {
		var me = this;
		
		if (me.viewer && me.viewer.close)
		{
			me.viewer.close();
		}
	}
});

IG$.controls.dashboard = new IG$.ctrlDashboardPanel({}, null);
