IG$.cVis.parallel = $s.extend(IG$.cVis._echart, {
	subtype: "parallel",
	draw: function(mresult) {
		var i,
			j,
			me = this,
			mcr = me.sheetoption ? me.sheetoption.model.chart_option : {},
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			tc = (data.length > 0) ? data[0].length : 0,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn,
			relationgroups = mcr.relationgroups;
	
		mcr.settings = mcr.settings || {};

		var jdom = $(me.container),
			w = IG$.j$ext._w(jdom),
			h = IG$.j$ext._h(jdom),
			sep = me.getSep();

		var box = $("<div></div>").appendTo(me.container);
		box.css({
			position: "absolute",
			top: 0,
			left: 0,
			right: 0,
			bottom: 0
		});

		var lineStyle = {
			width: 1,
			opacity: 0.5
			};
		var option = {
			chart: {
				renderTo: box[0]
			},
			echart_theme: mcr.echart_theme,
			legend: {
				bottom: 30,
				data: [],
				itemGap: 20,
				textStyle: {
					color: '#000',
					fontSize: 10
				}
			},
			tooltip: {
				padding: 10,
				backgroundColor: '#222',
				borderColor: '#777',
				borderWidth: 1
			},
			parallelAxis: [
				
			],
			visualMap: {
				show: true,
				min: 0,
				max: 150,
				dimension: 2,
				inRange: {
					color: ['#d94e5d', '#eac736', '#50a3ba'].reverse()
					// colorAlpha: [0, 1]
				}
			},
			parallel: {
				left: 50 + mcr.paddingleft,
				top: (mcr.title ? 55 : 35) + mcr.paddingtop,
				bottom: 30 + mcr.paddingbottom,
				right: 70 + mcr.paddingright,
				containLabel: true,
				parallelAxisDefault: {
					type: 'value',
					nameLocation: 'end',
					nameGap: 20,
					nameTextStyle: {
						fontSize: 10
					},
					axisLine: {
						lineStyle: {
							color: '#aaa'
						}
					},
					axisTick: {
						lineStyle: {
							color: '#777'
						}
					},
					splitLine: {
						show: false
					},
					axisLabel: {
						color: '#000'
					}
				}
			},
			series: [
				
			]
		};

		var parallelAxis = option.parallelAxis,
			series = option.series;
		
		for (i=0; i < fc; i++)
		{
			title = "";

			for (j=0; j < fr; j++)
			{
				title = (j==0 ? data[j][i].text : title + sep + data[j][i].text);
			}
			parallelAxis.push({
				dim: i,
				type: "category",
				name: title,
				data: [],
				cmap: {}
			});
		}

		for (i=fc; i < data[0].length; i++)
		{
			title = "";

			for (j=0; j < fr; j++)
			{
				title = (j==0 ? data[j][i].text : title + sep + data[j][i].text);
			}
			parallelAxis.push({
				dim: i,
				name: title
			});
		}

		for (i=0; i < fc; i++)
		{
			var paxis = parallelAxis[i];
			for (j=0; j < data.length; j++)
			{
				title = data[j][i].text || data[j][i].code;
				if (!paxis.cmap[title])
				{
					paxis.data.push(title);
					paxis.cmap[title] = 1;
				}
			}
		}

		var cars = [],
			cols = [],
			units = {},
			visible;

		for (i=fc; i < data[0].length; i++)
		{
			title = "";
			for (j=0; j < fr; j++)
			{
				title = (j == 0) ? data[j][i].text : title + sep + data[j][i].text;
			}

			units[title] = {name: title, unit: ""};
			cols.push(title);
		}

		var serie = {
			type: "parallel",
			lineStyle: lineStyle,
			data: []
		};

		series.push(serie);

		for (i=fr; i < data.length; i++)
		{
			title = "";
			var drow = [];
			for (j=0; j < fc; j++)
			{
				title = data[i][j].text || data[i][j].code;
				drow.push(title);
			}

			for (j=fc; j < data[i].length; j++)
			{
				title = Number(data[i][j].code);
				drow.push(title);
			}

			serie.data.push(drow);
		}

		me.drawmode = "echart";
		
		me.render([option], mresult);

		return [option];
	}
});