IG$.dynFilterDateConfig = {
	data: [
		{lname: "L_TODAY", value: "today"},
		{lname: "L_LAST_1D", value: "last1day"},
		{lname: "L_LAST_2D", value: "last2day"},
		{lname: "L_LAST_3D", value: "last3day"},
		{lname: "L_LAST_4D", value: "last4day"},
		{lname: "L_LAST_5D", value: "last5day"},
		{lname: "L_LAST_6D", value: "last6day"},
		{lname: "L_LAST_7D", value: "last7day"},
		{lname: "L_LAST_8D", value: "last8day"},
		{lname: "L_LAST_10D", value: "last10day"},
		{lname: "L_FROM_MON", value: "frweek"},
		{lname: "L_LAST_15D", value: "last15day"},
		{lname: "L_LAST_30D", value: "last30day"},
		{lname: "L_FROM_1ST_MON", value: "frmon"},
		{lname: "L_LAST_1M", value: "last1mon"},
		{lname: "L_LAST_2M", value: "last2mon"},
		{lname: "L_LAST_6M", value: "last6mon"},
		{lname: "L_LAST_1Y", value: "last1year"},
		{lname: "L_LAST_2Y", value: "last2year"},
		{lname: "L_LAST_3Y", value: "last3year"},
		{lname: "L_LAST_4Y", value: "last4year"},
		{lname: "L_LAST_5Y", value: "last5year"}
	],
	getValue: function(sel, st, ismonth, isyear) {
		var i,
			r = "",
			dt = new Date(),
			m, d, p;
			
		if (st == 0)
		{
			if (sel.indexOf("last") > -1)
			{
				if (sel.indexOf("day"))
				{
					for (i=1; i < 32; i++)
					{
						if (sel == "last" + (i) + "day")
						{
							dt.setDate(dt.getDate()-i);
							p = 1;
							break;
						}
					}
				}
				
				if (!p && sel.indexOf("mon"))
				{
					for (i=1; i < 13; i++)
					{
						if (sel == "last" + i + "mon")
						{
							dt.setMonth(dt.getMonth() - i);
							p = 1;
							break;
						}
					}
				}
				
				if (!p && sel.indexOf("year"))
				{
					for (i=1; i < 11; i++)
					{
						if (sel == "last" + i + "year")
						{
							dt.setMonth(dt.getMonth() - 12*i);
							p = 1;
							break;
						}
					}
				}
			}
			
			if (!p)
			{
				switch(sel)
				{
				case "today":
					break;
				case "frweek":
					startDay = 0;
					dt.setDate(dt.getDate()-(7 + dt.getDay() - startDay) % 7);
					break;
				case "frmon":
					dt.setDate(1);
					break;
				}
			}
		}
		
		m = (dt.getMonth()+1);
		m = (m < 10 ? "0" + m : m);
		d = dt.getDate();
		d = (d < 10 ? "0" + d : d);
		
		r = "" + dt.getFullYear() + (!isyear || ismonth ? "-" + m : "") + (!ismonth && !isyear ? "-" + d : "");
		
		return r;
	},
	
	transDate: function(pvalue) {
		var p = pvalue.split("-"),
			dt = new Date(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]));
			
		return dt;
	},
	
	initNames: function() {
		var me = this;
		if (!me._init_names)
		{
			$.each(me.data, function(i, k) {
				k.name = IRm$.r1(k.lname);
			});
			me._init_names = 1;
		}
	}
};

