	appendFiltering: function(dt) {
		var me = this,
			filter_items = me.filter_items,
			model_filter_items = me.sheetoption.model.filter_items,
			isformview = me.isformview;
			// i;

		if (!IG$.testVal("metric|measure|custommetric|formulameasure|multimetric|multimeasure|groupfield", dt.type.toLowerCase()))
		{
			if (isformview && !IG$["_FC_" + dt.type])
			{
				return;
			}
			else if (!isformview)
			{
				return;
			}
		}
		
		var ditem = {},
			datatype = dt.memo ? dt.memo.toLowerCase() : dt.memo;
		
		IG$.CopyObject(dt, ditem, "uid;name;nodepath;type;sql_id;objtype;options");
		ditem.uid = IG$.formatUID(ditem.uid);
		ditem.objtype = ditem.objtype || "text";
		ditem.fuid = "uid_" + (++me._fmax);
		ditem.title = ditem.name || (ditem.objtype + "_" + me._fmax);
		ditem.colspan = 4;
		
		switch (ditem.type.toLowerCase())
		{
		case "metric":
		case "custommetric":
			if (datatype == "date" || datatype == "datetime" || datatype == "timestamp")
			{
				ditem.operator = "EQ";
				ditem.objtype = "text";
			}
			else
			{
				ditem.operator = "LIKE";
				ditem.objtype = "text";
				ditem.showallvalue = true;
			}
			break;
		case "measure":
		case "formulameasure":
		case "measuregroup":
			ditem.operator = "GT";
			ditem.objtype = "text";
			break;
		}

		if (filter_items.length && filter_items[filter_items.length-1].objtype == "button")
		{
			filter_items.splice(filter_items.length - 1, 0, {
				model: ditem
			});
			model_filter_items.splice(model_filter_items.length - 1, 0, ditem);
		}
		else
		{
			filter_items.push({
				model: ditem
			});

			model_filter_items.push(ditem);
		}
		me.validateItems();
	},
	
	getPvalue: function(item) {
		var r = [],
			i,
			prows, prow;
		
		if (item.pvalues)
		{
			prows = item.pvalues.split("\n");
			
			for (i=0; i < prows.length; i++)
			{
				prow = prows[i].split(";");
				r.push({
					code: prow[0],
					disp: prow[1]
				});
			}
		}
		
		return r;
	},
	
