	_do_layout_worker: function(filter_items, contentarea) {
		var me = this,
			container = me.container,
			container_width = container.width(),
			filteroptions = me.sheetoption.model.filter_options,
			twidth = contentarea.width(), // innerWidth(),
			theight = contentarea.innerHeight(),
			toffset = contentarea.offset(),
			maxrowsize = 12,
			px_per_column = Math.floor(twidth / maxrowsize),
			gap = 4,
			// fcontainer, 
			rx = [], rh = [], mw = {}, mh = {},
			fitem, ttw = 0,
			p = me.p,
			f_t_dir;
			
		p && p.addClass("df-layout-normal");
		
		for (let i=0; i < filter_items.length; i++)
		{
			fitem = filter_items[i];
			f_t_dir = fitem.model.f_t_dir || filteroptions.f_t_dir;
			if (f_t_dir != "top")
			{
				if (fitem.objtype == "button" || (fitem.u2 && fitem.u2.iscontainer))
					continue;
				ttw = Math.max(ttw, IG$.j$ext._w(fitem.u3) + 10);
			}
		}
		
		let n = 0;
		
		$.each(filter_items, function(i, fitem) {
			var next_fitem = filter_items.length > i+1 ? filter_items[i+1] : null,
				next_fitem_model = next_fitem ? next_fitem.model : null,
				fmodel = fitem.model,
				tcab = fitem.u4,
				u1 = fitem.u1,
				lcap = fitem.lcap,
				loffset,
				colspan = fmodel.colspan || 1,
				next_colspan = next_fitem_model ? next_fitem.model.colspan || 1 : 0,
				rowfullheight = fmodel.rowfullheight,
				// ritem = filter_items.length > i+1 ? filter_items[i+1] : null,
				mwidth, mheight,
				f_t_dir = fmodel.f_t_dir || filteroptions.f_t_dir,
				cbox,
				crow,
				j;
			
			if (lcap)
			{
				fitem._owidth = lcap.width();
				fitem._dgap = u1.outerWidth(true) - u1.width();
			}
			
			if (ttw && !fmodel.merge_left && f_t_dir != "top")
			{
				// tcab.innerWidth(ttw);
				IG$.j$ext._w(tcab, ttw);
			}
			
			if (u1)
			{
				if (rowfullheight)
				{
					var copt = {};
					if (rowfullheight)
					{
						copt.height = "initial";
						lcap.addClass("df-full-height");
					} 
					lcap.css(copt);
					loffset = lcap.offset();
					
					mwidth = colspan * px_per_column;
					
					if (rowfullheight)
					{
						mheight = theight - (loffset.top - toffset.top) - 10;
						if (mheight)
						{
							u1.height(mheight);
						}
					}
				}
				else
				{
					mwidth = colspan  * px_per_column;
				}

				mwidth = Math.min(container_width, mwidth);
				
				// mwidth = Math.max(200, mwidth);
				u1.outerWidth(mwidth, true);
								
				if (fmodel.objtype == "checkbuttons")
				{
					cbox = $(".idv-checkbuttons", u1);
					cbox.removeClass("checkbutton-horizontal");
					
					if (fmodel.checkbuttonhor)
					{
						cbox.addClass("checkbutton-horizontal");
					}
				}
				else if (fmodel.objtype == "radiobuttons")
				{
					cbox = $(".mec-radiobuttons", u1);
					cbox.removeClass("checkbutton-horizontal");
					
					if (fmodel.checkbuttonhor)
					{
						cbox.addClass("checkbutton-horizontal");
					}
				}
				else
				{
					cbox = $(".idv-sel-combo", u1);
				}
				
				if (fitem.child && fitem.child.length && fitem.u2 && fitem.u2.iscontainer && fitem.u2.ui)
				{
					if (fitem.u2.objtype == "tabpanel")
					{
						$.each(fitem.child, function(j, tabchild) {
							me._do_layout_worker(tabchild, fitem.u2.getPage(j + 1).html);
						});
					}
					else
					{
						me._do_layout_worker(fitem.child, fitem.u2.ui);
					}
				}
			}
			
			fitem.u2 && fitem.u2.resize && fitem.u2.resize(); 
			/*
			u1 && u1.css({
				position: "relative"
			});
			*/
		});
		
		me._mbox = {
			rx: rx,
			rh: rh,
			mh: mh,
			mw: mw
		};
		
		if (filteroptions.f_bx_enable && me._sxbtn)
		{
			cy = gap;
			me._sxbtn.css({
				position: "relative"
			});
		}
		
		if (filteroptions.showbutton && me._sbtn)
		{
			cy = gap;
			me._sbtn.css({
				position: "relative"
			});
		}
		
		me.container.trigger("layout_completed");
	},
	
