	downloadExcel: function(isinstance, sheetview, multisheet, multisheet_items) {
		var me = this,
			report = me.report,
			sm = {}, 
			b_executed = 1,
			docitems = me.dzone.docitems;
			
		if (multisheet_items && multisheet_items.length && docitems)
		{
			$.each(multisheet_items, function(i, sid) {
				var j,
					s,
					drender;
				
				for (j=0; j < report.sheets.length; j++)
				{
					if (sid == "sheet_" + report.sheets[j].sheetindex)
					{
						s = report.sheets[j];
						break;
					}
				}
				
				if (s && s.renderBox)
				{
					drender = docitems[s.renderBox];
					
					if (drender && !drender.visible)
						return;
					
					if (!s.jobid)
					{
						b_executed = 0;
						return false;
					}
					
					sm[sid] = 1;
				}
			});
			
			if (!b_executed)
			{
				IG$.ShowError(IRm$.r1("L_RUN_RPT_FIRST"), me);
				return;
			}
		}
		
		me.report.downloadExcel(isinstance, sheetview, multisheet, sm);
	},
	
