IG$.objectSubscribe = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 500,
	height: 400,
	
	_confirm: function() {
		this.updateAuthConfig();
	},
	
	updateAuthConfig: function() {
		var me = this,
			req = new IG$._rpc$(),
			content,
			updateall = false,
			ctrl$updateall = me.down('[name=updateall]'),
			auth = '',
			dgrid = me.down("[name=datagridview]"),
			items = dgrid.store.data.items,
			record,
			i, d;
			
		if (ctrl$updateall.hidden == false && ctrl$updateall.getValue() == true)
		{
			updateall = true;
		}
		
		content = {
			option: "update_subscript",
			updateall: updateall,
			auths: []
		};
		
		for (i=0; i < items.length; i++)
		{
			record = items[i];
			d = record.data;
			
			content.auths.push({
				mtu: d.mtu,
				scid: d.scid,
				shared: d.shared == true
			});
		}
		
		req.init(me, 
			{
				ack: "authcontent",
				payload: {uid: this.uid, type: this.itemtype},
				mbody: content,
				meta_type: "auth_req"
			}, me, me.rs_updateAuthConfig, null);
		req.send();
	},
	
	rs_updateAuthConfig: function(xdoc) {
		var me = this;
		IG$.alertmsg(ig$.appname, IRm$.r1("M_SUCCESS"), null, me, 0, "success");
		me.callback && me.callback.execute();
		me.close();
	},
	
	init_f: function() {
		if (this.uid)
		{
			var me = this,
				req = new IG$._rpc$();
				
			req.init(me, 
				{
					ack: "authcontent",
					payload: {uid: me.uid, type: me.itemtype},
					mbody: {option: "subscription"}
				}, me, function(jdoc) {
					var i,
						data,
						dn;
					
					for (i=0; i < jdoc.length; i++)
					{
						jdoc[i].shared = jdoc[i].scid && jdoc[i].scid.length > 0;
					}
					// mgrid.addEventListener(MecGridEvent.DRAW_COMPLETED, drawCompleteHandler, false, 0, true);
					// mgrid.dataProvider = data.children();
					this.dataset = jdoc;
					this.down("[name=datagridview]").store.loadData(this.dataset);
				}, null);
			req.send();
		}
	},
	
	initComponent : function() {
		var me = this,
			ltype = me.itemtype.toLowerCase(),
			hassub = ltype == "folder" || ltype == "userdb";
		
		me.title = IRm$.r1('T_SUBSCR_AUTH');
		
		$s.apply(me, {
			items: [
				{
					xtype: "panel",
					layout: {
						type: 'vbox',
						align: 'stretch'
					},
					
					border: false,
					padding: ig$.padding,
					
					items: [
						{
							xtype: 'displayfield',
							value: IRm$.r1('L_AU_TITLE')
						},
						{
							xtype: "gridpanel",
							name: "datagridview",
							
							store: {
								fields: []
							},
							
							flex: 1,
							
							columns: [
								{
									text: IRm$.r1("B_TENANT"), // "Tenant",
									flex: 1,
									dataIndex: "mtname"
								},
								{
									xtype: 'checkcolumn',
									text: IRm$.r1("L_SHARED"),
									width: 50,
									sortable: false,
									dataIndex: 'shared',
									editor: {
										xtype: 'checkbox'
									}
								}
							]
						},
						{
							name: 'updateall',
							fieldLabel: IRm$.r1('B_OPTION'),
							xtype: 'checkbox',
							boxLabel: IRm$.r1('L_AU_APPLY_SUB'),
							checked: false,
							hidden: !hassub
						}
					]
				}	
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					var me = this;
					
					me.init_f();
				}
			}
		});
		
		IG$.objectSubscribe.superclass.initComponent.apply(this, arguments);
	}
});