IG$.helpWindow = $s.extend($s.window, {
	modal: true,
	layout: "fit",
	
	closable: true,
	resizable:false,
	
	uid: null,
	
	width: 600,
	height: 400,
	
	sK2/*loadContent*/: function(itemuid) {
		var panel=this,
			memo = panel.down("[name=memo]"),
			req = new IG$._rpc$();
		
		panel.uid = itemuid;

		memo.setValue(itemuid);
		
		req.init(panel, 
			{
				ack: "manual",
				payload: {uid: itemuid, doctype: panel.dm/*doctype*/},
				mbody: {option: "get"}
			}, panel, panel.rs_u4x/*loadContent*/, null);
		req.send();
	},
	
	rs_u4x/*loadContent*/: function(jdoc) {
		var me = this,
			helpdoc = this.down("[name=helpdoc]"),
			memo = this.down("[name=memo]"),
			helptitle = this.down("[name=helptitle]"),
			_ldoc,
			lcontent;
			
		me.u5x/*toolbarHandler*/("cmd_cancel");
			
		_ldoc = me._ldoc = jdoc;

		memo.setValue(me._ldoc.memo);
		
		var locale = window.useLocale || "en_US";
		
		lcontent = _ldoc.contents[locale] = _ldoc.contents[locale] || {lang: locale};
		
		me.setTitle(lcontent.title || IRm$.r1("B_HELP"));

		var doc = me.down("[name=helpdoc]"),
			helpdoc = me.down("[name=helpdocedit]"),
			content = lcontent.text || "";

		$(".igc-user-help", $(doc.body.dom)).html(content);
		helpdoc.setValue(content);
		helptitle.setValue(lcontent.title || "");
	},
	
	u5x/*toolbarHandler*/: function(cmd) {
		var me = this,
			instance = me.instance,
			win = me.win,
			btnedit = win ? win.down("[name=btnedit]") : null,
			btnsave = win ? win.down("[name=btnsave]") : null,
			btncancel = win ? win.down("[name=btncancel]") : null,
			p = me.down("[name=helpmain]"), active = -1,
			isadmin = instance.dlgLogin.jS2;
			
		switch (cmd)
		{
		case "cmd_edit":
			active = 1;
			break;
		case "cmd_save":
			me.u6x/*saveContent*/();
			break;
		case "cmd_cancel":
			if (btnedit && isadmin)
			{
				btnedit.setVisible(true);
				btnsave.setVisible(false);
			}
			active = 0;
			break;
		}
		
		if (active > -1)
		{
			p.setActiveItem(active);
		}
	},
	
	u7l/*updateContent*/: function() {
		var me = this,
			helpdoc = this.down("[name=helpdocedit]"),
			memo = this.down("[name=memo]"),
			helptitle = this.down("[name=helptitle]"),
			locale = window.useLocale || "en_US",
			_ldoc = me._ldoc,
			doc = _ldoc.contents[locale];
		
		doc.text = helpdoc.getValue();
		doc.title = helptitle.getValue();
	},
	
	u6x/*saveContent*/: function() {
		var panel=this,
			address,
			c, addr, _ldoc,
			req = new IG$._rpc$(),
			locale = window.useLocale || "en_US";
		 
		_ldoc = panel._ldoc || {};
	   
		lcontent = _ldoc.contents[locale] = _ldoc.contents[locale] || {lang: locale};
		
		panel.u7l/*updateContent*/();
		
		c = _ldoc;

		addr = {
			uid: panel.uid, 
			doctype: panel.dm/*doctype*/,
			option: "save"
		};

		if (!addr.uid)
		{
			addr.name = addr.memo;
			addr.type = "Help";
		}
		address = addr;
		
		req.init(panel, 
			{
				ack: "manual",
				payload: address,
				mbody: c,
				meta_type: "help_content"
			}, panel, panel.rs_u6x/*saveContent*/, null);
		req.send();
	},
	
	rs_u6x/*saveContent*/: function(jdoc) {
		var panel = this,
			uid = (jdoc) ? jdoc.uid : null;
		
		if (uid)
		{
			panel._ldoc.uid = uid;
		}
		
		IG$.alertmsg(ig$.appname, IRm$.r1("M_SAVED"), null, null, 0, "success");
	},
	
	initComponent : function() {
		var panel = this;
		
		$s.apply(this, {
			title: IRm$.r1("B_HELP"),
			items: [
				{
					xtype: "panel",
					layout: "fit",
					padding: ig$.padding,
					items: [
						{
							xtype: "panel",
							name: "helpmain",
							layout: "card",
							items: [
								{
									xtype: "panel",
									name: "helpdoc",
									html: "<div class='igc-user-help'></div>"
								},
								{
									xtype: "panel",
									name: "helpedit",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textfield",
											hidden: (panel.dm/*doctype*/ == "report") ? true : false,
											fieldLabel: "DOCID",
											name: "memo"
										},
										{
											xtype: "textfield",
											fieldLabel: IRm$.r1("B_TITLE"),
											name: "helptitle"
										},
										{
											xtype: "textarea",
											name: "helpdocedit",
											flex: 1,
											enableColors: true,
											enableAlignments: true
										}
									]
								}
							]
						}
					]
				}
			],
			buttons: [
				{
					text: IRm$.r1("B_EDIT"),
					hidden: this.dm/*doctype*/ != "report",
					name: "btnedit",
					handler: function() {
						var me = this,
							p = me.down("[name=peditor]");
						me.down("[name=btnsave]").setVisible(true);
						me.down("[name=btnedit]").setVisible(false);
						me.u5x/*toolbarHandler*/("cmd_edit");
					},
					scope: panel
				},
				{
					text: IRm$.r1("L_SAVE_CONTENT"),
					name: "btnsave",
					hidden: true,
					handler: function() {
						var me = this,
							p = me.down("[name=peditor]");
						me.u5x/*toolbarHandler*/("cmd_save");
					},
					scope: panel
				},
				{
					text: IRm$.r1("B_CLOSE"),
					name: "btncancel",
					handler: function() {
						panel.close();
					},
					scope: panel
				}
			],
			listeners: {
				afterrender: function() {
					var me = this;

					if (me.t != null && me.c != null)
					{
						me.setTitle(me.t || IRm$.r1("B_HELP"));
						var doc = this.down("[name=helpdoc]");
						if (doc.body)
							$(doc.body.dom).html(me.c);
					}
					else if (me.uid)
					{
						me.sK2/*loadContent*/(me.uid);
					}
				}
			}
		});
		
		IG$.helpWindow.superclass.initComponent.apply(this, arguments);
	}
});