IG$.V$grid.prototype.initializeDragDrop = function(el) {
	var me = this;
	
	me.dropFeedback = $('<div class="m-datagrid-feedback"></div>');
	me.dropFeedback.appendTo(me.owner);
	me.dropFeedback.hide();
};

IG$.V$grid.prototype.isAllowedType = function(dttype) {
	var r = false,
		dtypename = this.getTypeName(dttype);
	if (dtypename == "d" || dtypename == "m")
	{
		r = true;
	}
	return r;
}

IG$.V$grid.prototype.getTypeName = function(dttype) {
	var r = "";
	if (dttype == "measure" || dttype == "formulameasure" || dttype == "measuregroup")
	{
		r = "m";
	}
	else if (dttype == "metric" || dttype == "custommetric" || dttype == "tabdimension" || dttype == "measuregroupdimension")
	{
		r = "d";
	}
	return r;
};
