IG$.userpref = $s.extend($s.window, {
	modal: true,
	layout: "fit",
	
	closable: true,
	resizable:false,
	
	width: 500,
	autoHeight: true,
	
	_confirm: function() {
		var me = this,
			req = new IG$._rpc$(),
			nval = me.getFormatString();
			grdtz = me.down("[name=grdtz]"),
			dtz = me.dtz;
			
		if (me.tzloaded && grdtz.getSelectionModel().selected.length > 0)
		{
			dtz = grdtz.getSelectionModel().selected.items[0].get("id");
		}
		
		req.init(me, 
			{
				ack: "usercontent",
				payload: {address: "/user"},
				mbody: {
					option: "_gu_", 
					uid: me.uuid,
					dtz: dtz,
					dfrm: nval,
					a1: me.down("[name=a1]").getValue(),
					a2: me.down("[name=a2]").getValue()
				}
			}, me, function(jdoc) {
				this.close();
			});
		req.send();
	},
	
	loadConfig: function() {
		var panel = this,
			instance = panel.instance,
			req = new IG$._rpc$(),
			uuid = panel.uuid || instance.dlgLogin.logininfo.sid;
			
		panel.uuid = uuid;
		
		req.init(panel, 
			{
				ack: "usercontent",
				payload: {address: "/user"},
				mbody: {option: "_gi_", uid: uuid, tmpl: (IG$.__ep ? "sys_print_mode" : "")}
			}, panel, panel.rs_loadConfig);
		req.send();
	},
	
	rs_loadConfig: function(jdoc) {
		var me = this,
			tnode = jdoc.userdetail,
			dformat = tnode ? tnode.dfrm : "";
			
		dformat = dformat.replace(/\\&apos;/g, "'");
		
		$s.defaults(me, {
			dzt: tnode.dtz,
			a1: tnode.a1,
			a2: tnode.a2
		});

		me.down("[name=a1]").setValue(me.a1);
		me.down("[name=a2]").setValue(me.a2);
		
		me.updateForm(dformat);
	},
	
	updateForm: function(fval) {
		var me = this,
			f_order = me.down("[name=f_order]"),
			f_year = me.down("[name=f_year]"),
			f_month = me.down("[name=f_month]"),
			f_day = me.down("[name=f_day]"),
			f_ampm = me.down("[name=f_ampm]"),
			f_timezone = me.down("[name=f_timezone]"),
			f_datesep = me.down("[name=f_datesep]"),
			f_timesep = me.down("[name=f_timesep]"),
			f_wkday = me.down("[name=f_wkday]"),
			f_weekday = me.down("[name=f_weekday]"),
			f_wkdayod = me.down("[name=f_wkdayod]"),
			f, ny, nm, nd, dsep, md, fy;
		
		ny = fval.indexOf("y");
		nm = fval.indexOf("M");
		nd = fval.indexOf("d");
		
		if (nd < nm && nm < ny)
		{
			f = "DMY"; md = nm;
		}
		else if (ny < nm && nm < nd)
		{
			f = "YMD"; md = nm;
		}
		else if (nm < nd && nd < ny)
		{
			f = "MDY"; md = nd;
		}
		
		dsep = fval.charAt(md-1);
		f_datesep.setValue(dsep);
		
		f_order.setValue(f || "YMD");
		fy = fval.substring(ny, fval.lastIndexOf("y")+1);
		if (ny > 0 && fval.charAt(ny-1) == "'")
		{
			fy = "''" + fy;
		}
		f_year.setValue(fy);
		f_month.setValue(fval.substring(nm, fval.lastIndexOf("M")+1));
		f_day.setValue(fval.substring(nd, fval.lastIndexOf("d")+1));
		
		ny = fval.indexOf("E");
		f = (ny > -1) ? fval.substring(ny, fval.lastIndexOf("E")+1) : "EEEE";
		f_weekday.setValue(f);
		
		if (ny == 0)
		{
			f_wkdayod.setValue(true);
		}
		
		f_wkday.setValue(ny > -1);
		
		ny = fval.indexOf("a");
		f_ampm.setValue(ny > -1);
		
		dsep = fval.charAt(fval.indexOf("m") - 1);
		f_timesep.setValue(dsep);
	},
	
	loadTimeZone: function() {
		var panel = this,
			req = new IG$._rpc$();
			
		req.init(panel, 
			{
				ack: "helpcontent",
				payload: {},
				mbody: {option: "timezone"}
			}, panel, panel.rs_loadTimeZone);
		req.send();
	},
	
	rs_loadTimeZone: function(jdoc) {
		var me = this,
			tnode,
			tnodes,
			i, dp = [], 
			dp_tmpl = [],
			p,
			grdtz = me.down("[name=grdtz]"),
			a1 = me.down("[name=a1]"),
			a2 = me.down("[name=a2]");
			
		tnode = jdoc ? jdoc.timezone : null;
		
		if (tnode)
		{
			for (i=0; i < tnode.length; i++)
			{
				p = tnode[i];
				p.oh = p.offset / (1000*60*60);
			}
		}
		
		tnode = jdoc ? jdoc.app_tmpl : null;
		
		dp_tmpl.push({name: IRm$.r1("B_SELECT"), value: ""});
		
		if (tnode)
		{
			for (i=0; i < tnode.length; i++)
			{
				p = tnode[i];
				if (p.name.substring(0, 4) == "sys_")
				{
					tnode.splice(i, 1);
				}
				else
				{
					dp_tmpl.push(p);
				}
			}
		}
		
		a1.store.loadData(dp_tmpl);
		
		a1.setValue(me.a1 || "");
		
		me.tzloaded = true;
		grdtz.store.loadData(jdoc.timezone);
		
		for (i=0; i < grdtz.store.data.items.length; i++)
		{
			p = grdtz.store.data.items[i];
			if (p.get("id") == me.dtz)
			{
				grdtz.getSelectionModel().select(p);
				break;
			}
		}
	},
	
	getFormatString: function() {
		var me = this,
			f_order = me.down("[name=f_order]"),
			f_year = me.down("[name=f_year]"),
			f_month = me.down("[name=f_month]"),
			f_day = me.down("[name=f_day]"),
			f_ampm = me.down("[name=f_ampm]"),
			f_timezone = me.down("[name=f_timezone]"),
			f_datesep = me.down("[name=f_datesep]"),
			f_timesep = me.down("[name=f_timesep]"),
			f_wkday = me.down("[name=f_wkday]"),
			f_weekday = me.down("[name=f_weekday]"),
			f_wkdayod = me.down("[name=f_wkdayod]"),
			f,
			fd, fy, fm, fh;
		
		fy = f_year.getValue();
		fm = f_month.getValue();
		fd = f_day.getValue();
		fh = f_ampm.getValue() ? "hh" : "HH";
		
		switch (f_order.getValue())
		{
		case "DMY":
			f = [fd, fm, fy];
			break;
		case "YMD":
			f = [fy, fm, fd];
			break;
		case "MDY":
			f = [fm, fd, fy];
			break;
		}
		
		f = f.join(f_datesep.getValue());
		
		if (f_wkday.getValue())
		{
			f = (f_wkdayod.getValue()) ? f_weekday.getValue() + " " + f : f + " " + f_weekday.getValue();
		}
		
		f += " " + [fh, "mm", "ss"].join(f_timesep.getValue());
		
		f += f_ampm.getValue() ? " a" : "";
		f += f_timezone.getValue() ? ", z" : "";
		
		return f;
	},

	initComponent: function() {
		var me = this;
		
		me.title = IRm$.r1("L_PREFERENCES");
		
		$s.apply(this, {
			items: [
				{
					xtype: "tabpanel",
					minHeight: 400,
					minTabWidth: 120,
					deferredRender: false,
					defaults: {
						bodyPadding: ig$.padding
					},
					items: [
						{
							xtype: "form",
							title: IRm$.r1("L_DATE_FORMAT"),
							deferredRender: false,
							layout: "anchor",
							items: [
								{
									xtype: "combobox",
									queryMode: "local",
									editable: false,
									fieldLabel: IRm$.r1("L_DF_OS"),
									name: "f_order",
									valueField: "value",
									displayField: "name",
									store: {
										xtype: "store",
										fields: ["name", "value"],
										data: [
											{name: "Day Month Year", value: "DMY"},
											{name: "Year Month Day", value: "YMD"},
											{name: "Month Day Year", value: "MDY"}
										]
									}
								},
								{
									xtype: "combobox",
									queryMode: "local",
									editable: false,
									fieldLabel: IRm$.r1("L_DF_YF"),
									name: "f_year",
									valueField: "value",
									displayField: "name",
									store: {
										xtype: "store",
										fields: ["name", "value"],
										data: [
											{name: "2009", value: "yyyy"},
											{name: "09", value: "yy"},
											{name: "'09", value: "''yy"}
										]
									}
								},
								{
									xtype: "combobox",
									queryMode: "local",
									editable: false,
									name: "f_month",
									fieldLabel: IRm$.r1("L_DF_MF"),
									valueField: "value",
									displayField: "name",
									store: {
										xtype: "store",
										fields: ["name", "value"],
										data: [
											{name: "1", value: "M"},
											{name: "01", value: "MM"},
											{name: "January", value: "MMMMM"},
											{name: "Jan", value: "MMM"}
										]
									}
								},
								{
									xtype: "combobox",
									queryMode: "local",
									editable: false,
									name: "f_day",
									fieldLabel: IRm$.r1("L_DF_DF"),
									valueField: "value",
									displayField: "name",
									store: {
										xtype: "store",
										fields: ["name", "value"],
										data: [
											{name: "1", value: "d"},
											{name: "01", value: "dd"}
										]
									}
								},
								{
									xtype: "combobox",
									queryMode: "local",
									editable: false,
									name: "f_weekday",
									fieldLabel: IRm$.r1("L_DF_WF"),
									valueField: "value",
									displayField: "name",
									store: {
										xtype: "store",
										fields: ["name", "value"],
										data: [
											{name: "Monday", value: "EEEE"},
											{name: "Mon", value: "EEE"},
											{name: "Mo", value: "EE"},
											{name: "M", value: "E"}
										]
									}
								},
									{
									xtype: "fieldset",
									title: IRm$.r1("L_OPTIONS"),
									items: [
										{
											xtype: "checkbox",
											fieldLabel: IRm$.r1("L_DF_APM"),
											name: "f_ampm",
											boxLabel: IRm$.r1("B_SHOW")
										},
										{
											xtype: "checkbox",
											fieldLabel: IRm$.r1("L_DF_WD"),
											name: "f_wkday",
											boxLabel: IRm$.r1("B_SHOW")
										},
										{
											xtype: "checkbox",
											fieldLabel: IRm$.r1("L_DF_WD_O"),
											name: "f_wkdayod",
											boxLabel: IRm$.r1("L_SHOW_FIRST")
										},
										{
											xtype: "checkbox",
											name: "f_timezone",
											fieldLabel: IRm$.r1("L_TIMEZONE"),
											boxLabel: IRm$.r1("L_SHOW_TZ")
										},
										{
											xtype: "combobox",
											queryMode: "local",
											fieldLabel: IRm$.r1("L_DF_DS"),
											name: "f_datesep",
											editable: false,
											valueField: "value",
											displayField: "name",
											store: {
												xtype: "store",
												fields: ["name", "value"],
												data: [
													{name: ". (dot)", value: "."},
													{name: ": (colon)", value: ":"},
													{name: ", (comma)", value: ","},
													{name: "- (hypen)", value: "-"},
													{name: "/ (slash)", value: "/"},
													{name: "  (non)", value: ""}
												]
											}
										},
										{
											xtype: "combobox",
											queryMode: "local",
											fieldLabel: IRm$.r1("L_DF_TS"),
											name: "f_timesep",
											editable: false,
											valueField: "value",
											displayField: "name",
											store: {
												xtype: "store",
												fields: ["name", "value"],
												data: [
													{name: ": (colon)", value: ":"},
													{name: ". (dot)", value: "."},
													{name: ", (comma)", value: ","},
													{name: "- (hypen)", value: "-"},
													{name: "  (non)", value: ""}
												]
											}
										}
									]
								}
							]
						},
						{
							xtype: "form",
							title: IRm$.r1("L_TIMEZONE"),
							deferredRender: false,
							layout: "fit",
							items: [
								{
									xtype: "gridpanel",
									name: "grdtz",
									maxHeight: 380,
									selType: "checkboxmodel",
									selModel: {
										checkSelector: ".x-grid-cell",
										mode: "SINGLE"
									},
									store: {
										xtype: "store",
										fields: [
											"name", "offset", "id", "oh", "select"
										]
									},
									columns: [
										{
											text: IRm$.r1("B_ID"),
											dataIndex: "id",
											flex: 1
										},
										{
											text: IRm$.r1("B_NAME"),
											dataIndex: "name",
											flex: 1
										},
										{
											text: IRm$.r1("L_TZ_OFFSET"),
											dataIndex: "oh"
										}
									]
								}
							],
							listeners: {
								afterrender: function() {
									me.loadTimeZone();
								}
							}
						},
						{
							xtype: "form",
							title: IRm$.r1("L_APPL"),
							deferredRender: false,
							layout: "anchor",
							items: [
								{
									xtype: "combobox",
									name: "a1",
									fieldLabel: IRm$.r1("L_APPL_TMPL"),
									labelWidth: 120,
									queryMode: "local",
									editable: false,
									valueField: "value",
									displayField: "name",
									store: {
										xtype: "store",
										fields: ["name", "value"]
									}
								},
								{
									xtype: "combobox",
									name: "a2",
									fieldLabel: IRm$.r1("L_APPL_THEME"),
									labelWidth: 120,
									queryMode: "local",
									editable: false,
									valueField: "value",
									displayField: "name",
									store: {
										xtype: "store",
										fields: ["name", "value"]
									}
								}
							]
						}
					]
				}
			],
			buttons: [
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				},
				{
					text: IRm$.r1('B_CLOSE'),
					handler: function() {
						this.close();
					},
					scope: this
				}
			]
		});
		
		IG$.userpref.superclass.initComponent.call(this);
	},
	listeners: {
		afterrender: function(tobj) {
			tobj.loadConfig();
		}
	}
});