IG$.dlg_sel_objs = $s.extend($s.window, {
	width: 700,
	height: 550,
	layout: "fit",
	modal: true,
	
	bodyPadding: ig$.padding,
	
	move_selections: function(reverse, record) {
		var me = this,
			dbpool = me.down("[name=dbpool]"),
			cubeuid = dbpool.getValue(),
			tsrc = me.down("[name=" + (reverse ? "g_tgt" : "g_src") + "]"),
			ttgt = me.down("[name=" + (reverse ? "g_src" : "g_tgt") + "]"),
			sel = tsrc.getSelectionModel().selected,
			tsel = ttgt.getSelectionModel().selected,
			itemmap = {},
			rec,
			i;
		
		if (reverse == 1)
		{
			$.each(sel.items, function(s, record) {
				tsrc.store.remove(record);
			});
		}
		else
		{
			for (i=0; i < ttgt.store.data.items.length; i++)
			{
				itemmap[ttgt.store.data.items[i].get("uid")] = 1;
			}
			$.each(sel.items, function(s, rc) {
				var rctype = rc.get("type").toLowerCase();
													
				if (/(folder|table|inlineview|dataset)/.test(rctype) && !itemmap[rc.get("uid")])
				{
					rc.set("cubeuid", cubeuid);
					ttgt.store.add(rc);
				}
			});
		}
	},
	
	commit$f: function() {
		var me = this,
			g_tgt = me.down("[name=g_tgt]"),
			dbpool = me.down("[name=dbpool]"),
			dbvalue = dbpool.getValue(),
			g_sel = g_tgt.store.data.items,
			dp = [], i, rec,
			ds;
		
		if (!g_sel.length)
		{
			IG$.alertmsg(ig$.appname, IRm$.r1("L_SELECT_ITEM"), null, null, 0, "");
			return;
		}
		
		for (i=0; i < g_sel.length; i++)
		{
			dp.push(g_sel[i].data);
		}
		
		for (i=0; i < dbpool.store.data.items.length; i++)
		{
			rec = dbpool.store.data.items[i].data;
			
			if (rec.uid == dbvalue)
			{
				ds = {
					uid: rec.uid,
					name: rec.name,
					type: rec.type,
					nodepath: rec.nodepath
				};
				break;
			}
		}
		
		me.callback && me.callback.execute([dp, ds]);
		
		me.close();
	},
	
	initComponent: function() {
		var me = this;
		
		$s.apply(me, {
			title: IRm$.r1("L_SELECT_ITEMS"), // "Select items",
			
			items: [
				{
					xtype: "panel",
					flex: 1,
					layout: {
						type: "hbox",
						align: "stretch"
					},
					defaults:{
						padding: ig$.padding
					},
					items: [
						{
							xtype: "panel",
							title: IRm$.r1("L_AVAILABLE_OBJ"), // "Available objects",
							flex: 1,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "combobox",
									displayField: "name",
									name: "dbpool",
									valueField: "uid",
									fieldLabel: IRm$.r1("B_DATASOURCE"),
									store: {
										fields: ["name", "disp", "uid"] 
									},
									listeners: {
										change: function(tobj) {
											var me = this,
												tvalue = tobj.getValue(),
												bgroup = me.down("[name=bgroup]"),
												g_src = me.down("[name=g_src]"),
												troot;
											
											if (tvalue)
											{
												troot = {
													uid: tvalue,
													type: "ROOT",
													name: "Business items",
													leaf: false,
													expanded: true,
													children: [
														{
															type: "load",
															name: "Loading..."
														}
													]
												};
											}
											else
											{
												troot = {
													type: "ROOT",
													name: "Select source"
												};
											}
											
											troot = g_src.setRootNode(troot);
											
											if (troot.get("uid"))
											{
												troot.expand();
											}
										},
										scope: this
									}
								},
								new IG$.naviTree({
									instance: me.instance,
									showtoolbar: false,
									cubebrowse: true,
									ddGroup: "_I$RD_G_",
									name: "g_src",
									flex: 1,
									visibleItems: "folder;table;inlineview;dataset;",
									metatypes: "Table;Metric;InlineView;DataSet;Folder",
									enabledrag: true,
									border: 0,
									_search: true,
									isdatasource: true,
									custDblClickFunc: new IG$.callBackObj(me, function(record) {
										this.move_selections(0, record);
									})
								})
							]
						},
						{
							xtype: "container",
							width: 40,
							layout: "fit",
							items: [
								{
									xtype: "container",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "container",
											flex: 1
										},
										{
											xtype: "button",
											text: ">",
											handler: function() {
												me.move_selections(0);
											},
											scope: this
										},
										{
											xtype: "button",
											text: "<",
											handler: function() {
												me.move_selections(1);
											},
											scope: this
										},
										{
											xtype: "container",
											flex: 1
										}
									]
								}
							]
						},
						{
							xtype: "panel",
							title: IRm$.r1("L_SELECTED_OBJ"), // "Selected objects",
							flex: 1,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "fieldcontainer",
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textfield",
											name: "t_sel",
											emptyText: IRm$.r1("L_SEARCH_KWD"),
											labelWidth: 50,
											fieldLabel: IRm$.r1("B_SEARCH")
										},
										{
											xtype: "button",
											iconCls: "icon-toolbar-search",
											tooltip: IRm$.r1("B_SEARCH"),
											handler: function() {
												
											}
										}
									]
								},
								{
									xtype: "gridpanel",
									name: "g_tgt",
									selType: "checkboxmodel",
									selModel: {
										mode: "MULTI"
									},
									flex: 1,
									viewConfig: {
										plugins: {
											ptype: "gridviewdragdrop",
											ddGroup: "_I$RD_G_"
										},
										listeners: {
											beforedrop: function(node, data, dropRec, dropPosition, dropFunction) {
												var r = false,
													k, rc, p,
													itemmap = {},
													g_tgt = me.down("[name=g_tgt]"),
													dbpool = me.down("[name=dbpool]"),
													cubeuid = dbpool.getValue(),
													rctype;
												
												data.copy = true;
												
												for (k=0; k < g_tgt.store.data.items.length; k++)
												{
													rc = g_tgt.store.data.items[k];
													
													itemmap[rc.get("uid")] = 1;
												}
												
												for (k=0; k < data.records.length; k++)
												{
													rc = data.records[k];
													
													rctype = rc.get("type").toLowerCase();
													
													if (/(folder|table|inlineview|dataset)/.test(rctype) && !itemmap[rc.get("uid")])
													{
														p = {
															uid: rc.get("uid"),
															type: rc.get("type"),
															name: rc.get("name"),
															nodepath: rc.get("nodepath"),
															cubeuid: cubeuid 
														};
														
														itemmap[p.uid] = 1;
														this.store.add(p);
													}
												}
												
												return r;
											},
											drop: function(node, data, dropRec, dropPosition) {
												if (data.copy == false && dropRec)
												{
													
												}
											}
										}
									},
									ddGroup: "_I$RD_G_",
									enabledrop: true,
									enabledrag: false,
									store: {
										fields: ["name", "uid", "dbpool"]
									},
									columns: [
										{
											text: IRm$.r1("B_NAME"),
											flex: 1,
											width: 180,
											dataIndex: "name"
										},
										{
											text: IRm$.r1("L_DB_POOL"),
											width: 180,
											dataIndex: "dbpool"
										}
									],
									listeners: {
										itemdblclick: function(component, rec, node, rindex, e) {
											me.move_selections(1);
										},
										scope: this
									}
								}
							]
						}
					]
				}
			],
			buttons: [
				{
					xtype: "button",
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						me.commit$f();
					},
					scope: this
				},
				{
					xtype: "button",
					text: IRm$.r1("B_CANCEL"),
					handler: function() {
						this.close();
					},
					scope: this
				}
			]
		});
		
		IG$.dlg_sel_objs.superclass.initComponent.call(this);
	}
});